/* eslint-disable jsx-a11y/alt-text */
/* eslint-disable @next/next/no-img-element */

import { ImageResponse } from "next/og";

import { siteConfig } from "@/config/site";
import { cn } from "@/lib/utils";

export const runtime = "edge";

async function fetchImage(url: string) {
  const res = await fetch(url);
  const buffer = await res.arrayBuffer();
  return buffer;
}

async function fetchFonts() {
  const res = await fetch(
    new URL("../../../../public/fonts/CalSans-SemiBold.woff", import.meta.url)
  );

  const buffer = await res.arrayBuffer();

  return buffer;
}

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const title = searchParams.get("title")?.slice(0, 100) ?? siteConfig.name;
  const description =
    searchParams.get("description")?.slice(0, 300) ?? siteConfig.description;

  const defaultImage = new URL(siteConfig.image, siteConfig.url).toString();
  const imageUrl = searchParams.get("image") ?? defaultImage;
  const resolvedImageUrl = new URL(imageUrl, siteConfig.url).toString();

  const isSquaredImage = searchParams.get("square") === "true";

  const image = await fetchImage(resolvedImageUrl);
  const font = await fetchFonts();

  try {
    return new ImageResponse(
      (
        <div tw="relative flex h-full bg-black text-white">
          <svg
            viewBox="0 0 1024 1024"
            style={{
              transform: "translateX(-50%)",
              maskImage: "radial-gradient(closest-side,white,transparent)",
            }}
            // @ts-expect-error property 'tw' does not exist on type svg
            tw="absolute left-1/2 top-1/2 ml-0 h-[64rem] w-[64rem]"
          >
            <circle
              cx="512"
              cy="512"
              r="512"
              fill="url(#759c1415-0410-454c-8f7c-9a820de03641)"
              fillOpacity="0.7"
            />
            <defs>
              <radialGradient id="759c1415-0410-454c-8f7c-9a820de03641">
                <stop stopColor="#7775D6" />
                <stop offset="1" stopColor="#E935C1" />
              </radialGradient>
            </defs>
          </svg>

          <div tw="flex h-full w-1/2 flex-col justify-between px-12 py-24">
            <header tw="flex flex-col">
              <h1 tw="flex items-center text-4xl">
                <svg
                  viewBox="0 0 24 24"
                  fill="currentColor"
                  // @ts-expect-error property 'tw' does not exist on type svg
                  tw="mt-1.5 mr-1 h-10 w-10"
                >
                  <path
                    fill="CurrentColor"
                    d="M 19.6875 2 L 8.6875 3.5 C 7.6875 3.601563 7 4.5 7 5.5 L 7 15.78125 C 6.539063 15.699219 6.039063 15.699219 5.5 15.8125 C 3.601563 16.3125 2 17.988281 2 19.6875 C 2 21.386719 3.601563 22.40625 5.5 21.90625 C 7.398438 21.40625 9 19.699219 9 18 L 9 9.40625 L 20 7.9375 L 20 14.71875 C 19.539063 14.636719 19.039063 14.671875 18.5 14.8125 C 16.601563 15.3125 15 16.988281 15 18.6875 C 15 20.386719 16.601563 21.40625 18.5 20.90625 C 20.398438 20.40625 22 18.699219 22 17 L 22 4 C 22 2.800781 20.886719 1.898438 19.6875 2 Z"
                  />
                </svg>
                {title}
              </h1>

              <p tw="text-3xl font-medium">{description}</p>
            </header>

            <div tw="text-lg font-medium">
              {siteConfig.links.github.replace("https://", "")}
            </div>
          </div>

          <div tw="relative flex h-full w-1/2 overflow-hidden">
            <img
              // @ts-expect-error arrayBuffer is not assignable to string
              src={image}
              tw={cn(
                "mx-8 my-auto w-[56rem] max-w-none rounded-2xl border border-zinc-800 shadow-lg shadow-[#e935c277]",
                isSquaredImage && "w-[32rem]"
              )}
            />
          </div>
        </div>
      ),
      {
        width: 1200,
        height: 630,
        fonts: [
          {
            name: "heading",
            data: font,
            style: "normal",
          },
        ],
      }
    );
  } catch (e) {
    return new Response(`Failed to generate the image`, {
      status: 500,
    });
  }
}

"use client";

import React, { useEffect, useState } from "react";
import { zodResolver } from "@hookform/resolvers/zod";
import { Loader2, Upload, X } from "lucide-react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import { z } from "zod";

import { siteConfig } from "@/config/site";
import type { FirebaseArticle } from "@/types/firebase-article";
import { ARTICLE_CATEGORIES } from "@/types/firebase-article";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { useFirebaseAuth } from "@/context/firebase-auth-context";
import { useInvalidateAdminQueries } from "@/hooks/use-invalidate-admin-queries";
import { createArticle, updateArticle } from "@/lib/content-mutations-client";
import { isValidYouTubeUrl } from "@/lib/media-url-validation";
import { notifyIfNewlyPublished } from "@/lib/notify-if-published";
import { useTenantNotifyFields } from "@/hooks/use-tenant-notify-fields";
import { uploadSongFileLocal } from "@/lib/local-upload";
import { MAX_IMAGE_SIZE_LABEL, validateImageFile } from "@/lib/upload-limits";

const articleSchema = z
  .object({
    title: z.string().min(1, "Title is required"),
    category: z.string().min(1, "Category is required"),
    shortDescription: z.string().min(1, "Short description is required"),
    scriptureReference: z.string().optional(),
    content: z.string().min(1, "Full content is required"),
    author: z.string().min(1, "Author is required"),
    tags: z.string().optional(),
    youtubeUrl: z.string().optional(),
    featured: z.boolean(),
    isPublished: z.boolean(),
  })
  .superRefine((values, ctx) => {
    const youtube = values.youtubeUrl?.trim() ?? "";
    if (youtube && !isValidYouTubeUrl(youtube)) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Enter a valid YouTube URL (youtube.com or youtu.be)",
        path: ["youtubeUrl"],
      });
    }
  });

type ArticleFormValues = z.infer<typeof articleSchema>;

type AddArticleModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSave: () => void;
  initialArticle?: FirebaseArticle | null;
  churchId: string;
  contentScope?: "platform_public" | "organization";
};

function parseTags(tagsInput?: string): string[] {
  if (!tagsInput?.trim()) return [];
  return tagsInput
    .split(",")
    .map((tag) => tag.trim())
    .filter(Boolean);
}

function tagsToInput(tags?: string[]): string {
  return tags?.join(", ") ?? "";
}

function buildArticlePayload(values: ArticleFormValues) {
  return {
    title: values.title.trim(),
    category: values.category.trim(),
    shortDescription: values.shortDescription.trim(),
    scriptureReference: values.scriptureReference?.trim() || undefined,
    content: values.content.trim(),
    author: values.author.trim(),
    tags: parseTags(values.tags),
    youtubeUrl: values.youtubeUrl?.trim() || undefined,
    featured: values.featured,
    isPublished: values.isPublished,
  };
}

export function AddArticleModal({
  isOpen,
  onClose,
  onSave,
  initialArticle,
  churchId,
  contentScope = "organization",
}: AddArticleModalProps) {
  const { user, authUser } = useFirebaseAuth();
  const { invalidateArticles } = useInvalidateAdminQueries();
  const tenantFields = useTenantNotifyFields();
  const [coverFile, setCoverFile] = useState<File | undefined>();
  const [coverPreview, setCoverPreview] = useState("");
  const [loading, setLoading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);

  const form = useForm<ArticleFormValues>({
    resolver: zodResolver(articleSchema),
    defaultValues: {
      title: "",
      category: "Christian Living",
      shortDescription: "",
      scriptureReference: "",
      content: "",
      author: "",
      tags: "",
      youtubeUrl: "",
      featured: false,
      isPublished: false,
    },
  });

  useEffect(() => {
    if (initialArticle) {
      form.reset({
        title: initialArticle.title,
        category: initialArticle.category,
        shortDescription: initialArticle.shortDescription,
        scriptureReference: initialArticle.scriptureReference ?? "",
        content: initialArticle.content,
        author: initialArticle.author,
        tags: tagsToInput(initialArticle.tags),
        youtubeUrl: initialArticle.youtubeUrl ?? "",
        featured: initialArticle.featured,
        isPublished: initialArticle.isPublished,
      });
      setCoverPreview(initialArticle.coverImage ?? "");
    } else {
      form.reset({
        title: "",
        category: "Christian Living",
        shortDescription: "",
        scriptureReference: "",
        content: "",
        author: authUser?.displayName ?? "",
        tags: "",
        youtubeUrl: "",
        featured: false,
        isPublished: false,
      });
      setCoverPreview("");
    }
    setCoverFile(undefined);
    setUploadProgress(0);
  }, [initialArticle, isOpen, form, authUser?.displayName]);

  function handleCoverChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    const error = validateImageFile(file);
    if (error) {
      toast.error(error);
      e.target.value = "";
      return;
    }
    setCoverFile(file);
    const reader = new FileReader();
    reader.onloadend = () => setCoverPreview(reader.result as string);
    reader.readAsDataURL(file);
  }

  async function onSubmit(values: ArticleFormValues) {
    if (coverFile && validateImageFile(coverFile)) {
      toast.error(validateImageFile(coverFile)!);
      return;
    }

    if (!coverFile && !coverPreview.trim()) {
      toast.error("Cover image is required");
      return;
    }

    const createdBy =
      authUser?.email ?? authUser?.displayName ?? authUser?.uid ?? "admin";
    const payload = buildArticlePayload(values);

    setLoading(true);
    try {
      const idToken = user ? await user.getIdToken() : undefined;
      if (!idToken) {
        toast.error("You must be signed in to upload files.");
        return;
      }

      if (initialArticle) {
        await updateArticle(initialArticle.id, payload);

        let coverImageUrl = initialArticle.coverImage ?? "";
        if (coverFile) {
          const fd = new FormData();
          fd.append("file", coverFile);
          const url = await uploadSongFileLocal(
            initialArticle.id,
            "cover",
            fd,
            (p) => setUploadProgress(p),
            idToken,
            { kind: "article", replaceUrl: initialArticle.coverImage }
          );
          coverImageUrl = url;
          await updateArticle(initialArticle.id, { coverImage: url });
        }

        await notifyIfNewlyPublished({
          type: "article",
          contentId: initialArticle.id,
          contentTitle: payload.title,
          image: coverImageUrl,
          isPublished: payload.isPublished,
          wasPublished: initialArticle.isPublished,
          idToken,
          churchId,
          organizationId: tenantFields.organizationId,
        });

        toast.success("Article updated successfully");
      } else {
        const articleId = await createArticle({
          ...payload,
          contentScope,
          churchId: contentScope === "platform_public" ? "" : churchId,
          coverImage: "",
          createdBy,
        });

        let coverImageUrl = "";
        if (coverFile) {
          const fd = new FormData();
          fd.append("file", coverFile);
          const url = await uploadSongFileLocal(
            articleId,
            "cover",
            fd,
            (p) => setUploadProgress(p),
            idToken,
            { kind: "article" }
          );
          coverImageUrl = url;
          await updateArticle(articleId, { coverImage: url });
        }

        await notifyIfNewlyPublished({
          type: "article",
          contentId: articleId,
          contentTitle: payload.title,
          image: coverImageUrl,
          isPublished: payload.isPublished,
          idToken,
          churchId,
          organizationId: tenantFields.organizationId,
        });

        toast.success("Article added successfully");
      }

      await invalidateArticles();
      onSave();
      form.reset();
      setCoverFile(undefined);
      setCoverPreview("");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to save article");
    } finally {
      setLoading(false);
      setUploadProgress(0);
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open && !loading) onClose(); }}>
      <DialogContent className="max-h-[90dvh] overflow-y-auto sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{initialArticle ? "Edit Article" : "Add Article"}</DialogTitle>
          <DialogDescription>
            {initialArticle
              ? "Update article content, media links, and cover image"
              : `Publish a new article to ${siteConfig.name}`}
          </DialogDescription>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <Card className="border-border/50 shadow-none">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold">Article Details</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <FormField
                  control={form.control}
                  name="title"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Title</FormLabel>
                      <FormControl>
                        <Input placeholder="Article title" disabled={loading} {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="category"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Category</FormLabel>
                      <Select
                        onValueChange={field.onChange}
                        value={field.value}
                        disabled={loading}
                      >
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue placeholder="Select category" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {ARTICLE_CATEGORIES.map((category) => (
                            <SelectItem key={category} value={category}>
                              {category}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="shortDescription"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Short Description</FormLabel>
                      <FormControl>
                        <Textarea
                          placeholder="Brief summary shown on cards..."
                          rows={3}
                          disabled={loading}
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="scriptureReference"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Scripture Reference (optional)</FormLabel>
                      <FormControl>
                        <Input placeholder="Psalm 23:1" disabled={loading} {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="content"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Full Content</FormLabel>
                      <FormControl>
                        <Textarea
                          placeholder="Write the full article content..."
                          rows={8}
                          disabled={loading}
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="author"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Author</FormLabel>
                      <FormControl>
                        <Input placeholder="Author name" disabled={loading} {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="tags"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Tags (optional)</FormLabel>
                      <FormControl>
                        <Input
                          placeholder="Prayer, Worship, Faith (comma separated)"
                          disabled={loading}
                          {...field}
                        />
                      </FormControl>
                      <FormDescription>Comma-separated tags</FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="youtubeUrl"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>YouTube URL (optional)</FormLabel>
                      <FormControl>
                        <Input
                          placeholder="https://youtube.com/watch?v=... or https://youtu.be/..."
                          disabled={loading}
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </CardContent>
            </Card>

            <Card className="border-border/50 shadow-none">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold">Cover Image</CardTitle>
              </CardHeader>
              <CardContent className="space-y-2">
                <p className="text-xs text-muted-foreground">
                  Required · Max {MAX_IMAGE_SIZE_LABEL}
                </p>
                <div className="flex gap-4">
                  {coverPreview ? (
                    <div className="relative h-20 w-20 shrink-0">
                      <img
                        src={coverPreview}
                        alt="Cover preview"
                        className="h-full w-full rounded object-cover"
                      />
                      <button
                        type="button"
                        onClick={() => {
                          setCoverPreview(initialArticle?.coverImage ?? "");
                          setCoverFile(undefined);
                        }}
                        className="absolute -right-2 -top-2 rounded-full bg-destructive p-1 text-white"
                        disabled={loading}
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </div>
                  ) : null}
                  <label className="flex flex-1 cursor-pointer flex-col items-center justify-center rounded-lg border-2 border-dashed border-muted-foreground/50 p-4 transition-colors hover:border-primary">
                    <Upload className="mb-1 h-6 w-6 text-muted-foreground" />
                    <span className="text-xs font-medium">Click to upload</span>
                    <input
                      type="file"
                      accept=".jpg,.jpeg,.png,.webp,.gif,.avif,image/*"
                      onChange={handleCoverChange}
                      className="hidden"
                      disabled={loading}
                    />
                  </label>
                </div>
                {uploadProgress > 0 ? (
                  <p className="text-xs text-muted-foreground">Uploading… {uploadProgress}%</p>
                ) : null}
              </CardContent>
            </Card>

            <FormField
              control={form.control}
              name="featured"
              render={({ field }) => (
                <FormItem className="flex items-center justify-between rounded-lg border border-border/50 p-4">
                  <div className="space-y-0.5">
                    <FormLabel>Featured Article</FormLabel>
                    <p className="text-xs text-muted-foreground">
                      Highlight this article for future homepage features
                    </p>
                  </div>
                  <FormControl>
                    <Switch
                      checked={field.value}
                      onCheckedChange={field.onChange}
                      disabled={loading}
                    />
                  </FormControl>
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="isPublished"
              render={({ field }) => (
                <FormItem className="flex items-center justify-between rounded-lg border border-border/50 p-4">
                  <div className="space-y-0.5">
                    <FormLabel>Publish</FormLabel>
                    <p className="text-xs text-muted-foreground">
                      Make this article visible on the home page
                    </p>
                  </div>
                  <FormControl>
                    <Switch
                      checked={field.value}
                      onCheckedChange={field.onChange}
                      disabled={loading}
                    />
                  </FormControl>
                </FormItem>
              )}
            />

            <div className="flex justify-end gap-3 pt-2">
              <Button type="button" variant="outline" onClick={onClose} disabled={loading}>
                Cancel
              </Button>
              <Button type="submit" disabled={loading} className="gap-2">
                {loading ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    Saving...
                  </>
                ) : (
                  "Save Article"
                )}
              </Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useEffect, useState } from "react";
import { zodResolver } from "@hookform/resolvers/zod";
import { Loader2, Upload, X } from "lucide-react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";

import { siteConfig } from "@/config/site";
import type { FirebaseDonationCampaign } from "@/types/firebase-donation";
import { DONATION_CURRENCIES } from "@/types/firebase-donation";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import {
  createDonationCampaign,
  updateDonationCampaign,
} from "@/lib/donation-campaign-mutations";
import {
  donationCampaignFormSchema,
  type DonationCampaignFormValues,
} from "@/lib/donation-form-validation";
import { useFirebaseAuth } from "@/context/firebase-auth-context";
import { useInvalidateAdminQueries } from "@/hooks/use-invalidate-admin-queries";
import { notifyIfDonationCampaignPublished } from "@/lib/notify-if-published";
import { useTenantNotifyFields } from "@/hooks/use-tenant-notify-fields";
import { uploadSongFileLocal } from "@/lib/local-upload";
import { MAX_IMAGE_SIZE_LABEL, validateImageFile } from "@/lib/upload-limits";

type AddDonationCampaignModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSave: () => void;
  initialCampaign?: FirebaseDonationCampaign | null;
  churchId: string;
  contentScope?: "platform_public" | "organization";
};

export function AddDonationCampaignModal({
  isOpen,
  onClose,
  onSave,
  initialCampaign,
  churchId,
  contentScope = "organization",
}: AddDonationCampaignModalProps) {
  const { user, authUser } = useFirebaseAuth();
  const { invalidateDonations } = useInvalidateAdminQueries();
  const tenantFields = useTenantNotifyFields();
  const [bannerFile, setBannerFile] = useState<File | undefined>();
  const [bannerPreview, setBannerPreview] = useState("");
  const [loading, setLoading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);

  const form = useForm<DonationCampaignFormValues>({
    resolver: zodResolver(donationCampaignFormSchema),
    defaultValues: {
      title: "",
      description: "",
      targetAmount: 10000,
      currency: "INR",
      status: "inactive",
    },
  });

  useEffect(() => {
    if (initialCampaign) {
      form.reset({
        title: initialCampaign.title,
        description: initialCampaign.description,
        targetAmount: initialCampaign.targetAmount,
        currency: initialCampaign.currency,
        status: initialCampaign.status,
      });
      setBannerPreview(initialCampaign.bannerImage ?? "");
    } else {
      form.reset({
        title: "",
        description: "",
        targetAmount: 10000,
        currency: "INR",
        status: "inactive",
      });
      setBannerPreview("");
    }
    setBannerFile(undefined);
    setUploadProgress(0);
  }, [initialCampaign, isOpen, form]);

  function handleBannerChange(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;

    const error = validateImageFile(file);
    if (error) {
      toast.error(error);
      event.target.value = "";
      return;
    }

    setBannerFile(file);
    const reader = new FileReader();
    reader.onloadend = () => setBannerPreview(reader.result as string);
    reader.readAsDataURL(file);
  }

  async function onSubmit(values: DonationCampaignFormValues) {
    setLoading(true);
    try {
      const idToken = user ? await user.getIdToken() : undefined;
      if (!idToken) {
        toast.error("You must be signed in to upload files.");
        return;
      }
      const payload = {
        title: values.title.trim(),
        description: values.description.trim(),
        targetAmount: values.targetAmount,
        currency: values.currency,
        status: values.status,
        bannerImage: initialCampaign?.bannerImage ?? "",
      };

      if (initialCampaign) {
        const wasStatus = initialCampaign.status;
        await updateDonationCampaign(initialCampaign.id, payload);

        if (bannerFile) {
          const formData = new FormData();
          formData.append("file", bannerFile);
          const url = await uploadSongFileLocal(
            initialCampaign.id,
            "cover",
            formData,
            (progress) => setUploadProgress(progress),
            idToken,
            { kind: "donation", replaceUrl: initialCampaign.bannerImage }
          );
          await updateDonationCampaign(initialCampaign.id, { bannerImage: url });
        }

        await notifyIfDonationCampaignPublished({
          contentId: initialCampaign.id,
          contentTitle: payload.title,
          status: payload.status,
          wasStatus,
          idToken,
        });

        toast.success("Campaign updated successfully");
      } else {
        const campaignId = await createDonationCampaign({
          ...payload,
          contentScope,
          churchId: contentScope === "platform_public" ? "" : churchId,
          organizationId:
            contentScope === "platform_public" ? undefined : tenantFields.organizationId,
          branchId:
            contentScope === "platform_public" ? undefined : tenantFields.branchId,
        });

        if (bannerFile) {
          const formData = new FormData();
          formData.append("file", bannerFile);
          const url = await uploadSongFileLocal(
            campaignId,
            "cover",
            formData,
            (progress) => setUploadProgress(progress),
            idToken,
            { kind: "donation" }
          );
          await updateDonationCampaign(campaignId, { bannerImage: url });
        }

        await notifyIfDonationCampaignPublished({
          contentId: campaignId,
          contentTitle: payload.title,
          status: payload.status,
          idToken,
        });

        toast.success("Campaign created successfully");
      }

      await invalidateDonations();
      onSave();
      form.reset();
      setBannerFile(undefined);
      setBannerPreview("");
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : "Failed to save campaign"
      );
    } finally {
      setLoading(false);
      setUploadProgress(0);
    }
  }

  return (
    <Dialog
      open={isOpen}
      onOpenChange={(open) => {
        if (!open && !loading) onClose();
      }}
    >
      <DialogContent className="max-h-[90dvh] overflow-y-auto sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>
            {initialCampaign ? "Edit Campaign" : "Create Campaign"}
          </DialogTitle>
          <DialogDescription>
            {initialCampaign
              ? "Update campaign details and activate when ready"
              : `Create a new giving campaign for ${siteConfig.name}`}
          </DialogDescription>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="title"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Campaign Title</FormLabel>
                  <FormControl>
                    <Input placeholder="Building Fund 2026" disabled={loading} {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="description"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Description</FormLabel>
                  <FormControl>
                    <Textarea
                      placeholder="Explain how donations will be used"
                      rows={4}
                      disabled={loading}
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="grid gap-4 sm:grid-cols-2">
              <FormField
                control={form.control}
                name="targetAmount"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Target Amount</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        min={1}
                        step={1}
                        disabled={loading}
                        {...field}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="currency"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Currency</FormLabel>
                    <Select
                      disabled={loading}
                      onValueChange={field.onChange}
                      value={field.value}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select currency" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {DONATION_CURRENCIES.map((currency) => (
                          <SelectItem key={currency} value={currency}>
                            {currency}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <div className="space-y-2">
              <FormLabel>Banner Image</FormLabel>
              {bannerPreview ?
                <div className="relative overflow-hidden rounded-xl border border-border/50">
                  <img
                    src={bannerPreview}
                    alt="Campaign banner preview"
                    className="aspect-[16/9] w-full object-cover"
                  />
                  <Button
                    type="button"
                    size="icon"
                    variant="secondary"
                    className="absolute right-2 top-2 size-8 rounded-full"
                    onClick={() => {
                      setBannerPreview("");
                      setBannerFile(undefined);
                    }}
                  >
                    <X className="size-4" />
                  </Button>
                </div>
              : null}
              <label className="flex cursor-pointer flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-border/60 px-4 py-6 text-center transition-colors hover:bg-muted/30">
                <Upload className="size-5 text-muted-foreground" />
                <span className="text-xs text-muted-foreground">
                  Upload banner (max {MAX_IMAGE_SIZE_LABEL})
                </span>
                <input
                  type="file"
                  accept="image/*"
                  className="hidden"
                  disabled={loading}
                  onChange={handleBannerChange}
                />
              </label>
              {uploadProgress > 0 && uploadProgress < 100 ?
                <p className="text-xs text-muted-foreground">
                  Uploading… {uploadProgress}%
                </p>
              : null}
            </div>

            <FormField
              control={form.control}
              name="status"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Status</FormLabel>
                  <Select
                    disabled={loading}
                    onValueChange={field.onChange}
                    value={field.value}
                  >
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder="Select status" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      <SelectItem value="active">Active</SelectItem>
                      <SelectItem value="inactive">Inactive</SelectItem>
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="flex justify-end gap-2 pt-2">
              <Button type="button" variant="outline" onClick={onClose} disabled={loading}>
                Cancel
              </Button>
              <Button type="submit" disabled={loading}>
                {loading ?
                  <>
                    <Loader2 className="mr-2 size-4 animate-spin" />
                    Saving…
                  </>
                : initialCampaign ?
                  "Save Changes"
                : "Create Campaign"}
              </Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useEffect, useMemo, useState } from "react";
import { zodResolver } from "@hookform/resolvers/zod";
import { Loader2, Upload, X } from "lucide-react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";

import { siteConfig } from "@/config/site";
import type { FirebaseEvent } from "@/types/firebase-event";
import { EVENT_TYPES } from "@/types/firebase-event";

import { EventDatePicker } from "@/components/admin/event-date-picker";
import { EventTimePicker } from "@/components/admin/event-time-picker";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import {
  createEventFormSchema,
  type EventFormValues,
} from "@/lib/event-form-validation";
import { createEvent, updateEvent } from "@/lib/content-mutations-client";
import { notifyIfEventPublished } from "@/lib/notify-if-published";
import { useTenantNotifyFields } from "@/hooks/use-tenant-notify-fields";
import { uploadSongFileLocal } from "@/lib/local-upload";
import { MAX_IMAGE_SIZE_LABEL, validateImageFile } from "@/lib/upload-limits";
import { useFirebaseAuth } from "@/context/firebase-auth-context";
import { useInvalidateAdminQueries } from "@/hooks/use-invalidate-admin-queries";

type AddEventModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSave: () => void;
  initialEvent?: FirebaseEvent | null;
  churchId: string;
  contentScope?: "platform_public" | "organization";
};

export function AddEventModal({
  isOpen,
  onClose,
  onSave,
  initialEvent,
  churchId,
  contentScope = "organization",
}: AddEventModalProps) {
  const { user } = useFirebaseAuth();
  const { invalidateEvents } = useInvalidateAdminQueries();
  const tenantFields = useTenantNotifyFields();
  const [bannerFile, setBannerFile] = useState<File | undefined>();
  const [bannerPreview, setBannerPreview] = useState("");
  const [loading, setLoading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);

  const eventSchema = useMemo(
    () => createEventFormSchema(initialEvent?.eventDate),
    [initialEvent?.eventDate]
  );

  const form = useForm<EventFormValues>({
    resolver: zodResolver(eventSchema),
    defaultValues: {
      title: "",
      description: "",
      eventType: "Sunday Service",
      speakerName: "",
      eventDate: "",
      eventTime: "",
      location: "",
      status: "draft",
    },
  });

  useEffect(() => {
    if (initialEvent) {
      form.reset({
        title: initialEvent.title,
        description: initialEvent.description,
        eventType: initialEvent.eventType,
        speakerName: initialEvent.speakerName,
        eventDate: initialEvent.eventDate,
        eventTime: initialEvent.eventTime,
        location: initialEvent.location,
        status: initialEvent.status,
      });
      setBannerPreview(initialEvent.bannerImage ?? "");
    } else {
      form.reset({
        title: "",
        description: "",
        eventType: "Sunday Service",
        speakerName: "",
        eventDate: "",
        eventTime: "",
        location: "",
        status: "draft",
      });
      setBannerPreview("");
    }
    setBannerFile(undefined);
    setUploadProgress(0);
  }, [initialEvent, isOpen, form]);

  function handleBannerChange(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;

    const error = validateImageFile(file);
    if (error) {
      toast.error(error);
      event.target.value = "";
      return;
    }

    setBannerFile(file);
    const reader = new FileReader();
    reader.onloadend = () => setBannerPreview(reader.result as string);
    reader.readAsDataURL(file);
  }

  async function onSubmit(values: EventFormValues) {
    setLoading(true);
    try {
      const idToken = user ? await user.getIdToken() : undefined;
      if (!idToken) {
        toast.error("You must be signed in to upload files.");
        return;
      }

      const payload = {
        title: values.title.trim(),
        description: values.description.trim(),
        eventType: values.eventType,
        speakerName: values.speakerName.trim(),
        eventDate: values.eventDate,
        eventTime: values.eventTime.trim(),
        location: values.location.trim(),
        status: values.status,
        bannerImage: initialEvent?.bannerImage ?? "",
      };

      if (initialEvent) {
        await updateEvent(initialEvent.id, payload);

        let bannerImageUrl = initialEvent.bannerImage ?? "";
        if (bannerFile) {
          const formData = new FormData();
          formData.append("file", bannerFile);
          const url = await uploadSongFileLocal(
            initialEvent.id,
            "cover",
            formData,
            (progress) => setUploadProgress(progress),
            idToken,
            { kind: "event", replaceUrl: initialEvent.bannerImage }
          );
          await updateEvent(initialEvent.id, { bannerImage: url });
          bannerImageUrl = url;
        }

        await notifyIfEventPublished({
          contentId: initialEvent.id,
          contentTitle: payload.title,
          image: bannerImageUrl,
          status: payload.status,
          wasStatus: initialEvent.status,
          idToken,
          churchId,
          organizationId: tenantFields.organizationId,
        });

        toast.success("Event updated successfully");
      } else {
        const eventId = await createEvent({
          ...payload,
          contentScope,
          churchId: contentScope === "platform_public" ? "" : churchId,
        });

        let bannerImageUrl = payload.bannerImage;
        if (bannerFile) {
          const formData = new FormData();
          formData.append("file", bannerFile);
          const url = await uploadSongFileLocal(
            eventId,
            "cover",
            formData,
            (progress) => setUploadProgress(progress),
            idToken,
            { kind: "event" }
          );
          await updateEvent(eventId, { bannerImage: url });
          bannerImageUrl = url;
        }

        await notifyIfEventPublished({
          contentId: eventId,
          contentTitle: payload.title,
          image: bannerImageUrl,
          status: payload.status,
          idToken,
          churchId,
          organizationId: tenantFields.organizationId,
        });

        toast.success("Event created successfully");
      }

      await invalidateEvents();
      onSave();
      form.reset();
      setBannerFile(undefined);
      setBannerPreview("");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to save event");
    } finally {
      setLoading(false);
      setUploadProgress(0);
    }
  }

  return (
    <Dialog
      open={isOpen}
      onOpenChange={(open) => {
        if (!open && !loading) onClose();
      }}
    >
      <DialogContent className="max-h-[90dvh] overflow-y-auto sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{initialEvent ? "Edit Event" : "Create Event"}</DialogTitle>
          <DialogDescription>
            {initialEvent
              ? "Update event details and publish when ready"
              : `Add a new ministry event to ${siteConfig.name}`}
          </DialogDescription>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="title"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Event Title</FormLabel>
                  <FormControl>
                    <Input
                      placeholder="Sunday Worship Service"
                      disabled={loading}
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="description"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Description</FormLabel>
                  <FormControl>
                    <Textarea
                      placeholder="Full event description"
                      rows={4}
                      disabled={loading}
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="eventType"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Event Type</FormLabel>
                  <Select
                    disabled={loading}
                    onValueChange={field.onChange}
                    value={field.value}
                  >
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder="Select event type" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      {EVENT_TYPES.map((type) => (
                        <SelectItem key={type} value={type}>
                          {type}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="speakerName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Speaker Name</FormLabel>
                  <FormControl>
                    <Input
                      placeholder="Pastor name or guest speaker"
                      disabled={loading}
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="grid gap-4 sm:grid-cols-2">
              <FormField
                control={form.control}
                name="eventDate"
                render={({ field, fieldState }) => (
                  <FormItem className="flex flex-col">
                    <FormLabel>Event Date</FormLabel>
                    <FormControl>
                      <EventDatePicker
                        value={field.value}
                        onChange={field.onChange}
                        disabled={loading}
                        aria-invalid={fieldState.invalid}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="eventTime"
                render={({ field, fieldState }) => (
                  <FormItem className="flex flex-col">
                    <FormLabel>Event Time</FormLabel>
                    <FormControl>
                      <EventTimePicker
                        value={field.value}
                        onChange={field.onChange}
                        disabled={loading}
                        aria-invalid={fieldState.invalid}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <div className="space-y-2">
              <FormLabel>Banner Image</FormLabel>
              {bannerPreview ?
                <div className="relative overflow-hidden rounded-xl border border-border/50">
                  <img
                    src={bannerPreview}
                    alt="Event banner preview"
                    className="aspect-[16/9] w-full object-cover"
                  />
                  <Button
                    type="button"
                    size="icon"
                    variant="secondary"
                    className="absolute right-2 top-2 size-8 rounded-full"
                    onClick={() => {
                      setBannerPreview("");
                      setBannerFile(undefined);
                    }}
                  >
                    <X className="size-4" />
                  </Button>
                </div>
              : null}
              <label className="flex cursor-pointer flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-border/60 px-4 py-6 text-center transition-colors hover:bg-muted/30">
                <Upload className="size-5 text-muted-foreground" />
                <span className="text-xs text-muted-foreground">
                  Upload banner (max {MAX_IMAGE_SIZE_LABEL})
                </span>
                <input
                  type="file"
                  accept="image/*"
                  className="hidden"
                  disabled={loading}
                  onChange={handleBannerChange}
                />
              </label>
              {uploadProgress > 0 && uploadProgress < 100 ?
                <p className="text-xs text-muted-foreground">
                  Uploading… {uploadProgress}%
                </p>
              : null}
            </div>

            <FormField
              control={form.control}
              name="location"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Location</FormLabel>
                  <FormControl>
                    <Input
                      placeholder="Church sanctuary or venue"
                      disabled={loading}
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="status"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Status</FormLabel>
                  <Select
                    disabled={loading}
                    onValueChange={field.onChange}
                    value={field.value}
                  >
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder="Select status" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      <SelectItem value="draft">Draft</SelectItem>
                      <SelectItem value="published">Published</SelectItem>
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="flex justify-end gap-2 pt-2">
              <Button type="button" variant="outline" onClick={onClose} disabled={loading}>
                Cancel
              </Button>
              <Button type="submit" disabled={loading}>
                {loading ?
                  <>
                    <Loader2 className="mr-2 size-4 animate-spin" />
                    Saving…
                  </>
                : initialEvent ?
                  "Save Changes"
                : "Create Event"}
              </Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { Loader2, Upload, X } from "lucide-react";
import { toast } from "sonner";

import type { FirebaseSong, SongCategory } from "@/types/firebase-song";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { addSong, updateSong } from "@/lib/content-mutations-client";
import { useFirebaseAuth } from "@/context/firebase-auth-context";
import { useInvalidateAdminQueries } from "@/hooks/use-invalidate-admin-queries";
import { useSubscriptionOptional } from "@/context/subscription-context";
import { useTenantNotifyFields } from "@/hooks/use-tenant-notify-fields";
import { notifyIfNewlyPublished } from "@/lib/notify-if-published";
import { SONG_CATEGORIES } from "@/types/firebase-song";
import { uploadSongFileLocal } from "@/lib/local-upload";
import {
  MAX_AUDIO_SIZE_LABEL,
  MAX_IMAGE_SIZE_LABEL,
  validateAudioFile,
  validateImageFile,
} from "@/lib/upload-limits";

type AddMusicModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSave: () => void;
  initialSong?: FirebaseSong | null;
  churchId: string;
  contentScope?: "platform_public" | "organization";
};

type SongFormData = {
  songTitle: string;
  alternateTitle: string;
  artist: string;
  category: SongCategory;
  originalLyrics: string;
  translationLyrics: string;
  scriptureReference: string;
  tags: string;
  featured: boolean;
  published: boolean;
  youtubeUrl: string;
};

type UploadProgress = {
  cover: number;
  audio: number;
};

const EMPTY_FORM: SongFormData = {
  songTitle: "",
  alternateTitle: "",
  artist: "",
  category: "Worship",
  originalLyrics: "",
  translationLyrics: "",
  scriptureReference: "",
  tags: "",
  featured: false,
  published: true,
  youtubeUrl: "",
};

function UploadProgressBar({
  label,
  percent,
}: {
  label: string;
  percent: number;
}) {
  if (percent <= 0) return null;

  return (
    <div className="space-y-1">
      <div className="flex justify-between text-xs text-muted-foreground">
        <span>{label}</span>
        <span>{percent}%</span>
      </div>
      <div className="h-2 overflow-hidden rounded-full bg-muted">
        <div
          className="h-full rounded-full bg-primary transition-all duration-200"
          style={{ width: `${percent}%` }}
        />
      </div>
    </div>
  );
}

function FormSection({
  title,
  description,
  children,
}: {
  title: string;
  description?: string;
  children: React.ReactNode;
}) {
  return (
    <section className="space-y-4 rounded-xl border border-border/50 bg-muted/20 p-4">
      <div>
        <h3 className="text-sm font-semibold text-foreground">{title}</h3>
        {description ? (
          <p className="mt-0.5 text-xs text-muted-foreground">{description}</p>
        ) : null}
      </div>
      <div className="space-y-4">{children}</div>
    </section>
  );
}

function songToFormData(song: FirebaseSong): SongFormData {
  return {
    songTitle: song.songTitle || song.englishTitle || song.title || "",
    alternateTitle: song.alternateTitle ?? song.teluguTitle ?? "",
    artist: song.artist ?? "",
    category: song.category ?? "Worship",
    originalLyrics: song.originalLyrics || song.lyrics || "",
    translationLyrics:
      song.translationLyrics ?? song.transliteratedLyrics ?? "",
    scriptureReference: song.scriptureReference ?? "",
    tags: song.tags?.join(", ") ?? "",
    featured: song.featured ?? false,
    published: song.published !== false,
    youtubeUrl: song.youtubeUrl || "",
  };
}

export function AddMusicModal({
  isOpen,
  onClose,
  onSave,
  initialSong,
  churchId,
  contentScope = "organization",
}: AddMusicModalProps) {
  const { user } = useFirebaseAuth();
  const { invalidateSongs } = useInvalidateAdminQueries();
  const subscription = useSubscriptionOptional();
  const tenantFields = useTenantNotifyFields();
  const [formData, setFormData] = useState<SongFormData>(EMPTY_FORM);
  const [files, setFiles] = useState<{ cover?: File; audio?: File }>({});
  const [coverPreview, setCoverPreview] = useState("");
  const [loading, setLoading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState<UploadProgress>({
    cover: 0,
    audio: 0,
  });

  useEffect(() => {
    if (initialSong) {
      setFormData(songToFormData(initialSong));
      setCoverPreview(initialSong.imageUrl || "");
    } else {
      setFormData(EMPTY_FORM);
      setCoverPreview("");
    }
    setFiles({});
    setUploadProgress({ cover: 0, audio: 0 });
  }, [initialSong, isOpen]);

  function handleInputChange(
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  }

  function isValidYouTubeUrl(url: string) {
    if (!url) return true;
    return /(youtube\.com\/watch\?v=|youtube\.com\/embed\/|youtu\.be\/)/i.test(
      url.trim()
    );
  }

  function handleFileChange(
    e: React.ChangeEvent<HTMLInputElement>,
    type: "cover" | "audio"
  ) {
    const file = e.target.files?.[0];
    if (!file) return;

    const error =
      type === "cover" ? validateImageFile(file) : validateAudioFile(file);
    if (error) {
      toast.error(error);
      e.target.value = "";
      return;
    }

    setFiles((prev) => ({ ...prev, [type]: file }));

    if (type === "cover") {
      const reader = new FileReader();
      reader.onloadend = () => setCoverPreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  }

  async function uploadFile(
    songId: string,
    fileType: "cover" | "audio",
    file: File,
    idToken: string,
    onProgress?: (percent: number) => void
  ): Promise<string> {
    onProgress?.(10);
    const fd = new FormData();
    fd.append("file", file);
    onProgress?.(30);
    return uploadSongFileLocal(songId, fileType, fd, (percent) => {
      onProgress?.(30 + percent * 0.7);
    }, idToken, {
      kind: "song",
      replaceUrl:
        fileType === "cover" ? initialSong?.imageUrl : initialSong?.audioUrl,
    });
  }

  function buildSongPayload() {
    const tags = formData.tags
      .split(",")
      .map((tag) => tag.trim())
      .filter(Boolean);

    return {
      songTitle: formData.songTitle.trim(),
      alternateTitle: formData.alternateTitle.trim() || undefined,
      artist: formData.artist.trim() || undefined,
      category: formData.category,
      originalLyrics: formData.originalLyrics,
      translationLyrics: formData.translationLyrics.trim() || undefined,
      scriptureReference: formData.scriptureReference.trim() || undefined,
      tags,
      featured: formData.featured,
      published: formData.published,
      youtubeUrl: formData.youtubeUrl.trim() || undefined,
    };
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    if (!formData.songTitle.trim()) {
      toast.error("Song title is required");
      return;
    }

    if (files.cover && validateImageFile(files.cover)) {
      toast.error(validateImageFile(files.cover)!);
      return;
    }

    if (files.audio && validateAudioFile(files.audio)) {
      toast.error(validateAudioFile(files.audio)!);
      return;
    }

    if (formData.youtubeUrl && !isValidYouTubeUrl(formData.youtubeUrl)) {
      toast.error("YouTube URL must be a valid youtube.com or youtu.be link");
      return;
    }

    if (!initialSong && subscription && !subscription.checkUsageLimit("songs")) {
      return;
    }

    setLoading(true);
    setUploadProgress({ cover: 0, audio: 0 });

    try {
      const idToken = user ? await user.getIdToken() : undefined;
      if (!idToken) {
        toast.error("You must be signed in to upload files.");
        return;
      }
      const payload = buildSongPayload();
      const wasPublished = initialSong?.published !== false;

      if (initialSong) {
        await updateSong(initialSong.id, payload);

        const mediaUpdates: { imageUrl?: string; audioUrl?: string } = {};
        if (files.cover) {
          mediaUpdates.imageUrl = await uploadFile(
            initialSong.id,
            "cover",
            files.cover,
            idToken,
            (p) => setUploadProgress((prev) => ({ ...prev, cover: p }))
          );
        }
        if (files.audio) {
          mediaUpdates.audioUrl = await uploadFile(
            initialSong.id,
            "audio",
            files.audio,
            idToken,
            (p) => setUploadProgress((prev) => ({ ...prev, audio: p }))
          );
        }
        if (Object.keys(mediaUpdates).length > 0) {
          await updateSong(initialSong.id, mediaUpdates);
        }

        if (payload.published && !wasPublished) {
          await notifyIfNewlyPublished({
            type: "song",
            contentId: initialSong.id,
            contentTitle: payload.songTitle,
            image: mediaUpdates.imageUrl ?? initialSong.imageUrl ?? "",
            isPublished: true,
            wasPublished,
            idToken,
            churchId: tenantFields.churchId ?? churchId,
            organizationId: tenantFields.organizationId,
          });
        }

        toast.success("Song updated successfully");
      } else {
        const songId = await addSong(
          contentScope === "platform_public" ? "" : (tenantFields.churchId ?? churchId),
          {
            ...payload,
            contentScope,
            imageUrl: "",
            audioUrl: "",
          },
          {
            branchId: tenantFields.branchId,
            organizationIdFallback: tenantFields.organizationId,
          }
        );

        const mediaUpdates: { imageUrl?: string; audioUrl?: string } = {};
        if (files.cover) {
          mediaUpdates.imageUrl = await uploadFile(
            songId,
            "cover",
            files.cover,
            idToken,
            (p) => setUploadProgress((prev) => ({ ...prev, cover: p }))
          );
        }
        if (files.audio) {
          mediaUpdates.audioUrl = await uploadFile(
            songId,
            "audio",
            files.audio,
            idToken,
            (p) => setUploadProgress((prev) => ({ ...prev, audio: p }))
          );
        }
        if (Object.keys(mediaUpdates).length > 0) {
          await updateSong(songId, mediaUpdates);
        }

        await notifyIfNewlyPublished({
          type: "song",
          contentId: songId,
          contentTitle: payload.songTitle,
          image: mediaUpdates.imageUrl ?? "",
          isPublished: payload.published,
          idToken,
          churchId: tenantFields.churchId ?? churchId,
          organizationId: tenantFields.organizationId,
        });

        toast.success("Song added successfully");
      }

      await invalidateSongs();
      onSave();
      setFormData(EMPTY_FORM);
      setFiles({});
      setCoverPreview("");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to save song");
    } finally {
      setLoading(false);
      setUploadProgress({ cover: 0, audio: 0 });
    }
  }

  return (
    <Dialog
      open={isOpen}
      onOpenChange={(open) => {
        if (!open && !loading) onClose();
      }}
    >
      <DialogContent className="max-h-[90dvh] overflow-y-auto sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>{initialSong ? "Edit Song" : "Add New Song"}</DialogTitle>
          <DialogDescription>
            {initialSong
              ? "Update song details, media, lyrics, and publishing options."
              : "Add a worship song for your church or ministry library."}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-5">
          <FormSection
            title="Basic Information"
            description="Core details shown across the song library."
          >
            <div className="space-y-2">
              <Label htmlFor="songTitle">Song Title *</Label>
              <Input
                id="songTitle"
                name="songTitle"
                value={formData.songTitle}
                onChange={handleInputChange}
                placeholder="e.g. How Great Thou Art"
                required
                disabled={loading}
              />
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="alternateTitle">Alternate Title</Label>
                <Input
                  id="alternateTitle"
                  name="alternateTitle"
                  value={formData.alternateTitle}
                  onChange={handleInputChange}
                  placeholder="Translation or local title"
                  disabled={loading}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="artist">Artist / Worship Team</Label>
                <Input
                  id="artist"
                  name="artist"
                  value={formData.artist}
                  onChange={handleInputChange}
                  placeholder="e.g. Hillsong Worship"
                  disabled={loading}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="category">Category</Label>
              <Select
                value={formData.category}
                onValueChange={(value: SongCategory) =>
                  setFormData((prev) => ({ ...prev, category: value }))
                }
                disabled={loading}
              >
                <SelectTrigger id="category">
                  <SelectValue placeholder="Select category" />
                </SelectTrigger>
                <SelectContent>
                  {SONG_CATEGORIES.map((category) => (
                    <SelectItem key={category} value={category}>
                      {category}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </FormSection>

          <FormSection
            title="Media"
            description="Cover art, audio recording, and optional video."
          >
            <div className="space-y-2">
              <Label htmlFor="cover">Cover Image</Label>
              <p className="text-xs text-muted-foreground">
                Max {MAX_IMAGE_SIZE_LABEL}
              </p>
              <div className="flex gap-4">
                {coverPreview ? (
                  <div className="relative h-20 w-20 shrink-0">
                    <img
                      src={coverPreview}
                      alt="Cover preview"
                      className="h-full w-full rounded object-cover"
                    />
                    <button
                      type="button"
                      onClick={() => {
                        setCoverPreview(initialSong?.imageUrl ?? "");
                        setFiles((prev) => {
                          const next = { ...prev };
                          delete next.cover;
                          return next;
                        });
                      }}
                      className="absolute -right-2 -top-2 rounded-full bg-destructive p-1 text-white"
                      disabled={loading}
                    >
                      <X className="h-3 w-3" />
                    </button>
                  </div>
                ) : null}
                <label className="flex flex-1 cursor-pointer flex-col items-center justify-center rounded-lg border-2 border-dashed border-muted-foreground/50 p-4 transition-colors hover:border-primary">
                  <Upload className="mb-1 h-6 w-6 text-muted-foreground" />
                  <span className="text-xs font-medium">Click to upload</span>
                  <input
                    type="file"
                    id="cover"
                    accept=".jpg,.jpeg,.png,.webp,.gif,.avif,image/*"
                    onChange={(e) => handleFileChange(e, "cover")}
                    className="hidden"
                    disabled={loading}
                  />
                </label>
              </div>
              <UploadProgressBar label="Cover upload" percent={uploadProgress.cover} />
            </div>

            <div className="space-y-2">
              <Label htmlFor="audio">Audio File</Label>
              <p className="text-xs text-muted-foreground">
                Max {MAX_AUDIO_SIZE_LABEL}
              </p>
              {files.audio ? (
                <div className="mb-2 flex items-center justify-between rounded-lg bg-muted p-2">
                  <span className="truncate text-sm">{files.audio.name}</span>
                  <button
                    type="button"
                    onClick={() =>
                      setFiles((prev) => {
                        const next = { ...prev };
                        delete next.audio;
                        return next;
                      })
                    }
                    className="rounded-full p-1 hover:bg-destructive/20"
                    disabled={loading}
                  >
                    <X className="h-4 w-4" />
                  </button>
                </div>
              ) : null}
              <label className="flex cursor-pointer flex-col items-center justify-center rounded-lg border-2 border-dashed border-muted-foreground/50 p-4 transition-colors hover:border-primary">
                <Upload className="mb-1 h-6 w-6 text-muted-foreground" />
                <span className="text-xs font-medium">Click to upload</span>
                <input
                  type="file"
                  id="audio"
                  accept=".mp3,.wav,.m4a,audio/*"
                  onChange={(e) => handleFileChange(e, "audio")}
                  className="hidden"
                  disabled={loading}
                />
              </label>
              <UploadProgressBar label="Audio upload" percent={uploadProgress.audio} />
            </div>

            <div className="space-y-2">
              <Label htmlFor="youtubeUrl">YouTube Video URL</Label>
              <Input
                id="youtubeUrl"
                name="youtubeUrl"
                value={formData.youtubeUrl}
                onChange={handleInputChange}
                placeholder="https://youtube.com/watch?v=... or https://youtu.be/..."
                disabled={loading}
              />
            </div>
          </FormSection>

          <FormSection
            title="Lyrics"
            description="English lyrics and optional translated / transliterated lyrics."
          >
            <div className="space-y-2">
              <Label htmlFor="translationLyrics">English Lyrics</Label>
              <Textarea
                id="translationLyrics"
                name="translationLyrics"
                value={formData.translationLyrics}
                onChange={handleInputChange}
                placeholder="Enter English lyrics..."
                rows={5}
                disabled={loading}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="originalLyrics">Translated Lyrics</Label>
              <Textarea
                id="originalLyrics"
                name="originalLyrics"
                value={formData.originalLyrics}
                onChange={handleInputChange}
                placeholder="Enter transliterated or translated lyrics..."
                rows={5}
                disabled={loading}
              />
            </div>
          </FormSection>

          <FormSection
            title="Publishing"
            description="Metadata and visibility for the public library."
          >
            <div className="space-y-2">
              <Label htmlFor="scriptureReference">Scripture Reference</Label>
              <Input
                id="scriptureReference"
                name="scriptureReference"
                value={formData.scriptureReference}
                onChange={handleInputChange}
                placeholder="e.g. Psalm 23:1"
                disabled={loading}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="tags">Tags</Label>
              <Input
                id="tags"
                name="tags"
                value={formData.tags}
                onChange={handleInputChange}
                placeholder="e.g. communion, revival, Sunday service"
                disabled={loading}
              />
              <p className="text-xs text-muted-foreground">
                Separate tags with commas.
              </p>
            </div>

            <div className="flex items-center justify-between rounded-lg border border-border/50 bg-background px-4 py-3">
              <div>
                <Label htmlFor="featured">Featured Song</Label>
                <p className="text-xs text-muted-foreground">
                  Highlight this song in featured areas.
                </p>
              </div>
              <Switch
                id="featured"
                checked={formData.featured}
                onCheckedChange={(checked) =>
                  setFormData((prev) => ({ ...prev, featured: checked }))
                }
                disabled={loading}
              />
            </div>

            <div className="flex items-center justify-between rounded-lg border border-border/50 bg-background px-4 py-3">
              <div>
                <Label htmlFor="published">Publish</Label>
                <p className="text-xs text-muted-foreground">
                  Make this song visible to the public library.
                </p>
              </div>
              <Switch
                id="published"
                checked={formData.published}
                onCheckedChange={(checked) =>
                  setFormData((prev) => ({ ...prev, published: checked }))
                }
                disabled={loading}
              />
            </div>
          </FormSection>

          <div className="flex justify-end gap-3 pt-2">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              disabled={loading}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={loading} className="gap-2">
              {loading ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  {uploadProgress.cover > 0 || uploadProgress.audio > 0
                    ? "Uploading..."
                    : "Saving..."}
                </>
              ) : (
                "Save Song"
              )}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { zodResolver } from "@hookform/resolvers/zod";
import { Loader2, Upload, X } from "lucide-react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import { z } from "zod";

import { siteConfig } from "@/config/site";
import type { FirebaseSermon } from "@/types/firebase-sermon";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { useFirebaseAuth } from "@/context/firebase-auth-context";
import { useInvalidateAdminQueries } from "@/hooks/use-invalidate-admin-queries";
import { createSermon, updateSermon } from "@/lib/content-mutations-client";
import {
  isValidAudioUrl,
  isValidYouTubeUrl,
} from "@/lib/media-url-validation";
import { notifyIfNewlyPublished } from "@/lib/notify-if-published";
import { useTenantNotifyFields } from "@/hooks/use-tenant-notify-fields";
import { uploadSongFileLocal } from "@/lib/local-upload";
import { MAX_IMAGE_SIZE_LABEL, validateImageFile } from "@/lib/upload-limits";

const sermonSchema = z
  .object({
    title: z.string().min(1, "Title is required"),
    subtitle: z.string().optional(),
    scriptureReference: z.string().min(1, "Scripture reference is required"),
    speaker: z.string().min(1, "Speaker / Pastor is required"),
    shortDescription: z.string().min(1, "Short description is required"),
    content: z.string().min(1, "Sermon content is required"),
    tags: z.string().optional(),
    youtubeUrl: z.string().optional(),
    audioUrl: z.string().optional(),
    isPublished: z.boolean(),
  })
  .superRefine((values, ctx) => {
    const youtube = values.youtubeUrl?.trim() ?? "";
    const audio = values.audioUrl?.trim() ?? "";

    if (youtube && !isValidYouTubeUrl(youtube)) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Enter a valid YouTube URL (youtube.com or youtu.be)",
        path: ["youtubeUrl"],
      });
    }

    if (audio && !isValidAudioUrl(audio)) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Enter a valid audio URL (http, https, or /uploads/...)",
        path: ["audioUrl"],
      });
    }
  });

type SermonFormValues = z.infer<typeof sermonSchema>;

type AddSermonModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSave: () => void;
  initialSermon?: FirebaseSermon | null;
  churchId: string;
  contentScope?: "platform_public" | "organization";
};

function parseTags(tagsInput?: string): string[] {
  if (!tagsInput?.trim()) return [];
  return tagsInput
    .split(",")
    .map((tag) => tag.trim())
    .filter(Boolean);
}

function tagsToInput(tags?: string[]): string {
  return tags?.join(", ") ?? "";
}

function buildSermonPayload(values: SermonFormValues) {
  return {
    title: values.title.trim(),
    subtitle: values.subtitle?.trim() || undefined,
    scriptureReference: values.scriptureReference.trim(),
    speaker: values.speaker.trim(),
    shortDescription: values.shortDescription.trim(),
    content: values.content.trim(),
    tags: parseTags(values.tags),
    youtubeUrl: values.youtubeUrl?.trim() || undefined,
    audioUrl: values.audioUrl?.trim() || undefined,
    isPublished: values.isPublished,
  };
}

export function AddSermonModal({
  isOpen,
  onClose,
  onSave,
  initialSermon,
  churchId,
  contentScope = "organization",
}: AddSermonModalProps) {
  const { user, authUser } = useFirebaseAuth();
  const { invalidateSermons } = useInvalidateAdminQueries();
  const tenantFields = useTenantNotifyFields();
  const [coverFile, setCoverFile] = useState<File | undefined>();
  const [coverPreview, setCoverPreview] = useState("");
  const [loading, setLoading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);

  const form = useForm<SermonFormValues>({
    resolver: zodResolver(sermonSchema),
    defaultValues: {
      title: "",
      subtitle: "",
      scriptureReference: "",
      speaker: "",
      shortDescription: "",
      content: "",
      tags: "",
      youtubeUrl: "",
      audioUrl: "",
      isPublished: false,
    },
  });

  useEffect(() => {
    if (initialSermon) {
      form.reset({
        title: initialSermon.title,
        subtitle: initialSermon.subtitle ?? "",
        scriptureReference: initialSermon.scriptureReference,
        speaker: initialSermon.speaker,
        shortDescription: initialSermon.shortDescription,
        content: initialSermon.content,
        tags: tagsToInput(initialSermon.tags),
        youtubeUrl: initialSermon.youtubeUrl ?? "",
        audioUrl: initialSermon.audioUrl ?? "",
        isPublished: initialSermon.isPublished,
      });
      setCoverPreview(initialSermon.coverImage ?? "");
    } else {
      form.reset({
        title: "",
        subtitle: "",
        scriptureReference: "",
        speaker: "",
        shortDescription: "",
        content: "",
        tags: "",
        youtubeUrl: "",
        audioUrl: "",
        isPublished: false,
      });
      setCoverPreview("");
    }
    setCoverFile(undefined);
    setUploadProgress(0);
  }, [initialSermon, isOpen, form]);

  function handleCoverChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    const error = validateImageFile(file);
    if (error) {
      toast.error(error);
      e.target.value = "";
      return;
    }
    setCoverFile(file);
    const reader = new FileReader();
    reader.onloadend = () => setCoverPreview(reader.result as string);
    reader.readAsDataURL(file);
  }

  async function onSubmit(values: SermonFormValues) {
    if (coverFile && validateImageFile(coverFile)) {
      toast.error(validateImageFile(coverFile)!);
      return;
    }

    if (!coverFile && !coverPreview.trim()) {
      toast.error("Cover image is required");
      return;
    }

    const createdBy =
      authUser?.email ?? authUser?.displayName ?? authUser?.uid ?? "admin";
    const payload = buildSermonPayload(values);

    setLoading(true);
    try {
      const idToken = user ? await user.getIdToken() : undefined;
      if (!idToken) {
        toast.error("You must be signed in to upload files.");
        return;
      }

      if (initialSermon) {
        await updateSermon(initialSermon.id, payload);

        let coverImageUrl = initialSermon.coverImage ?? "";
        if (coverFile) {
          const fd = new FormData();
          fd.append("file", coverFile);
          const url = await uploadSongFileLocal(
            initialSermon.id,
            "cover",
            fd,
            (p) => setUploadProgress(p),
            idToken,
            { kind: "sermon", replaceUrl: initialSermon.coverImage }
          );
          coverImageUrl = url;
          await updateSermon(initialSermon.id, { coverImage: url });
        }

        await notifyIfNewlyPublished({
          type: "sermon",
          contentId: initialSermon.id,
          contentTitle: payload.title,
          image: coverImageUrl,
          isPublished: payload.isPublished,
          wasPublished: initialSermon.isPublished,
          idToken,
          churchId,
          organizationId: tenantFields.organizationId,
        });

        toast.success("Sermon updated successfully");
      } else {
        const sermonId = await createSermon({
          ...payload,
          contentScope,
          churchId: contentScope === "platform_public" ? "" : churchId,
          coverImage: "",
          createdBy,
        });

        let coverImageUrl = "";
        if (coverFile) {
          const fd = new FormData();
          fd.append("file", coverFile);
          const url = await uploadSongFileLocal(
            sermonId,
            "cover",
            fd,
            (p) => setUploadProgress(p),
            idToken,
            { kind: "sermon" }
          );
          coverImageUrl = url;
          await updateSermon(sermonId, { coverImage: url });
        }

        await notifyIfNewlyPublished({
          type: "sermon",
          contentId: sermonId,
          contentTitle: payload.title,
          image: coverImageUrl,
          isPublished: payload.isPublished,
          idToken,
          churchId,
          organizationId: tenantFields.organizationId,
        });

        toast.success("Sermon added successfully");
      }

      await invalidateSermons();
      onSave();
      form.reset();
      setCoverFile(undefined);
      setCoverPreview("");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to save sermon");
    } finally {
      setLoading(false);
      setUploadProgress(0);
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open && !loading) onClose(); }}>
      <DialogContent className="max-h-[90dvh] overflow-y-auto sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{initialSermon ? "Edit Sermon" : "Add Sermon"}</DialogTitle>
          <DialogDescription>
            {initialSermon
              ? "Update sermon details, media links, and cover image"
              : `Publish a new sermon to ${siteConfig.name}`}
          </DialogDescription>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <Card className="border-border/50 shadow-none">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold">Sermon Details</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <FormField
                  control={form.control}
                  name="title"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Title</FormLabel>
                      <FormControl>
                        <Input placeholder="Sermon title" disabled={loading} {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="subtitle"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Subtitle (optional)</FormLabel>
                      <FormControl>
                        <Input placeholder="Optional subtitle" disabled={loading} {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="scriptureReference"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Scripture Reference</FormLabel>
                      <FormControl>
                        <Input placeholder="John 3:16" disabled={loading} {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="speaker"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Speaker / Pastor</FormLabel>
                      <FormControl>
                        <Input placeholder="Pastor name" disabled={loading} {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="shortDescription"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Short Description</FormLabel>
                      <FormControl>
                        <Textarea
                          placeholder="Brief summary for cards and search..."
                          rows={3}
                          disabled={loading}
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="content"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Sermon Content</FormLabel>
                      <FormControl>
                        <Textarea
                          placeholder="Full sermon notes or transcript..."
                          rows={8}
                          disabled={loading}
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="tags"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Tags (optional)</FormLabel>
                      <FormControl>
                        <Input
                          placeholder="faith, grace, salvation"
                          disabled={loading}
                          {...field}
                        />
                      </FormControl>
                      <FormDescription>Comma-separated tags</FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="youtubeUrl"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>YouTube URL (optional)</FormLabel>
                      <FormControl>
                        <Input
                          placeholder="https://youtube.com/watch?v=... or https://youtu.be/..."
                          disabled={loading}
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="audioUrl"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Audio URL (optional)</FormLabel>
                      <FormControl>
                        <Input
                          placeholder="https://example.com/sermon.mp3"
                          disabled={loading}
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </CardContent>
            </Card>

            <Card className="border-border/50 shadow-none">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold">Cover Image</CardTitle>
              </CardHeader>
              <CardContent className="space-y-2">
                <p className="text-xs text-muted-foreground">
                  Required · Max {MAX_IMAGE_SIZE_LABEL}
                </p>
                <div className="flex gap-4">
                  {coverPreview ? (
                    <div className="relative h-20 w-20 shrink-0">
                      <img
                        src={coverPreview}
                        alt="Cover preview"
                        className="h-full w-full rounded object-cover"
                      />
                      <button
                        type="button"
                        onClick={() => {
                          setCoverPreview(initialSermon?.coverImage ?? "");
                          setCoverFile(undefined);
                        }}
                        className="absolute -right-2 -top-2 rounded-full bg-destructive p-1 text-white"
                        disabled={loading}
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </div>
                  ) : null}
                  <label className="flex flex-1 cursor-pointer flex-col items-center justify-center rounded-lg border-2 border-dashed border-muted-foreground/50 p-4 transition-colors hover:border-primary">
                    <Upload className="mb-1 h-6 w-6 text-muted-foreground" />
                    <span className="text-xs font-medium">Click to upload</span>
                    <input
                      type="file"
                      accept=".jpg,.jpeg,.png,.webp,.gif,.avif,image/*"
                      onChange={handleCoverChange}
                      className="hidden"
                      disabled={loading}
                    />
                  </label>
                </div>
                {uploadProgress > 0 ? (
                  <p className="text-xs text-muted-foreground">Uploading… {uploadProgress}%</p>
                ) : null}
              </CardContent>
            </Card>

            <FormField
              control={form.control}
              name="isPublished"
              render={({ field }) => (
                <FormItem className="flex items-center justify-between rounded-lg border border-border/50 p-4">
                  <div className="space-y-0.5">
                    <FormLabel>Publish</FormLabel>
                    <p className="text-xs text-muted-foreground">
                      Make this sermon visible on the home page
                    </p>
                  </div>
                  <FormControl>
                    <Switch
                      checked={field.value}
                      onCheckedChange={field.onChange}
                      disabled={loading}
                    />
                  </FormControl>
                </FormItem>
              )}
            />

            <div className="flex justify-end gap-3 pt-2">
              <Button type="button" variant="outline" onClick={onClose} disabled={loading}>
                Cancel
              </Button>
              <Button type="submit" disabled={loading} className="gap-2">
                {loading ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    Saving...
                  </>
                ) : (
                  "Save Sermon"
                )}
              </Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useEffect } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import {
  BookOpen,
  CalendarDays,
  FileText,
  ListMusic,
  Mic2,
  Users,
} from "lucide-react";

import { MultiOrgDashboard } from "@/components/admin/multi-org-dashboard";
import { WelcomeCard } from "@/components/admin/welcome-card";
import { DashboardBranchSwitcher } from "@/components/dashboard/dashboard-branch-switcher";
import { AdminPageHeader } from "@/components/admin/admin-page-header";
import { PlanBadgeFromContext } from "@/components/subscription/plan-badge-from-context";
import { adminSectionClass } from "@/lib/responsive-classes";
import {
  AnalyticsRecentLists,
} from "@/components/admin/analytics/analytics-recent-lists";
import {
  AnalyticsStatCards,
  type AnalyticsStatDefinition,
} from "@/components/admin/analytics/analytics-stat-cards";
import { useAdminAnalytics } from "@/hooks/use-admin-analytics";
import { useAdminChurchBlocked } from "@/hooks/use-admin-collections";
import { DashboardQueryPrefetch } from "@/components/admin/dashboard-query-prefetch";
import { useOrganization } from "@/context/organization-context";
import { isMultiChurchOrgWorkspace } from "@/lib/organization/workspace-type";

const TAB_REDIRECTS: Record<string, string> = {
  songs: "/dashboard/content?tab=songs",
  sermons: "/dashboard/content?tab=sermons",
  articles: "/dashboard/content?tab=articles",
  events: "/dashboard/content?tab=events",
  donations: "/dashboard/content?tab=donations",
  prayers: "/dashboard/content?tab=prayers",
  churches: "/dashboard/churches",
};

export function AdminDashboard() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { organization } = useOrganization();
  const isMultiOrg = isMultiChurchOrgWorkspace(organization);
  const analytics = useAdminAnalytics();
  const blocked = useAdminChurchBlocked();

  useEffect(() => {
    const tab = searchParams.get("tab");
    if (tab && TAB_REDIRECTS[tab]) {
      router.replace(TAB_REDIRECTS[tab]);
    }
  }, [router, searchParams]);

  if (isMultiOrg) {
    return <MultiOrgDashboard />;
  }

  const statCards: AnalyticsStatDefinition[] = [
    {
      key: "songs",
      label: "Songs",
      value: analytics.counts.songs,
      icon: ListMusic,
    },
    {
      key: "sermons",
      label: "Sermons",
      value: analytics.counts.sermons,
      icon: Mic2,
    },
    {
      key: "articles",
      label: "Articles",
      value: analytics.counts.articles,
      icon: FileText,
    },
    {
      key: "events",
      label: "Events",
      value: analytics.counts.events,
      icon: CalendarDays,
    },
    {
      key: "users",
      label: "Members",
      value: analytics.counts.users,
      icon: Users,
    },
  ];

  return (
    <div className={adminSectionClass}>
      <DashboardQueryPrefetch />
      <AdminPageHeader
        eyebrow="Overview"
        title="Dashboard"
        description={`${analytics.scopeLabel} · ministry overview`}
      >
        <DashboardBranchSwitcher />
        <PlanBadgeFromContext />
      </AdminPageHeader>

      <WelcomeCard />

      {blocked ? (
        <div className="rounded-xl border border-amber-500/30 bg-amber-500/5 px-4 py-3 text-sm text-amber-800 dark:text-amber-200">
          Your church workspace is still loading. Select a church to view
          analytics and manage content.
        </div>
      ) : null}

      <AnalyticsStatCards
        stats={statCards}
        loading={analytics.loading || analytics.insightsLoading}
      />

      <AnalyticsRecentLists
        recentUsers={analytics.recentUsers}
        recentDonations={analytics.recentDonations}
        loading={analytics.loading}
        insightsLoading={analytics.insightsLoading}
      />
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { Edit2, FileText, Loader2, Trash2 } from "lucide-react";
import { toast } from "sonner";

import type { FirebaseArticle } from "@/types/firebase-article";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { DEFAULT_SONG_COVER } from "@/config/site";
import { deleteArticle } from "@/lib/content-mutations-client";
import { getSongCoverUrl } from "@/lib/utils";

type ArticleListProps = {
  articles: FirebaseArticle[];
  loading: boolean;
  onEdit: (article: FirebaseArticle) => void;
  onDelete: () => void;
};

export function ArticleList({
  articles,
  loading,
  onEdit,
  onDelete,
}: ArticleListProps) {
  const [deleting, setDeleting] = useState<string | null>(null);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [selected, setSelected] = useState<FirebaseArticle | null>(null);

  async function handleConfirmDelete() {
    if (!selected) return;
    setDeleting(selected.id);
    try {
      await deleteArticle(selected.id);
      toast.success("Article deleted");
      onDelete();
    } catch {
      toast.error("Failed to delete article");
    } finally {
      setDeleting(null);
      setDeleteConfirmOpen(false);
      setSelected(null);
    }
  }

  if (loading) {
    return (
      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        <div className="flex flex-col items-center justify-center gap-3 py-20">
          <Loader2 className="h-7 w-7 animate-spin text-primary/60" />
          <p className="text-sm text-muted-foreground">Loading articles…</p>
        </div>
      </div>
    );
  }

  if (articles.length === 0) {
    return (
      <div className="overflow-hidden rounded-2xl border border-dashed border-border/60 bg-card/50 shadow-sm">
        <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-muted">
            <FileText className="h-5 w-5 text-muted-foreground" />
          </div>
          <div>
            <p className="text-sm font-medium">No articles have been created for this church yet.</p>
            <p className="mt-0.5 text-xs text-muted-foreground">
              Add your first article to get started.
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        <div className="border-b border-border/50 bg-muted/30 px-4 py-3 sm:px-6">
          <div className="flex items-center justify-between">
            <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-muted-foreground">
              All Articles
            </p>
            <p className="text-xs text-muted-foreground">
              {articles.length} {articles.length === 1 ? "article" : "articles"}
            </p>
          </div>
        </div>

        <div className="divide-y divide-border/40">
          {articles.map((article, index) => {
            const coverSrc = getSongCoverUrl(article.coverImage);
            const isDeleting = deleting === article.id;

            return (
              <div
                key={article.id}
                className="flex items-center gap-3 px-4 py-3 transition-colors hover:bg-accent/30 sm:gap-4 sm:px-6 sm:py-3.5"
              >
                <span className="hidden w-5 shrink-0 text-center text-xs text-muted-foreground/50 sm:block">
                  {index + 1}
                </span>

                <div className="relative h-11 w-11 shrink-0 overflow-hidden rounded-lg border border-border/50 shadow-sm">
                  <img
                    src={coverSrc}
                    alt={article.title}
                    className="h-full w-full object-cover"
                    onError={(e) => {
                      e.currentTarget.src = DEFAULT_SONG_COVER;
                    }}
                  />
                </div>

                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-semibold text-foreground">
                    {article.title}
                  </p>
                  <div className="mt-1 flex flex-wrap items-center gap-1.5">
                    <span className="inline-flex rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-medium text-primary">
                      {article.category}
                    </span>
                    {article.featured ? (
                      <span className="inline-flex rounded-full bg-amber-500/10 px-2 py-0.5 text-[10px] font-medium text-amber-600 dark:text-amber-400">
                        Featured
                      </span>
                    ) : null}
                    <span className="text-[10px] text-muted-foreground">
                      by {article.author}
                    </span>
                    <span
                      className={`inline-flex rounded-full px-2 py-0.5 text-[10px] font-medium ${
                        article.isPublished
                          ? "bg-accent text-muted-foreground"
                          : "bg-muted text-muted-foreground"
                      }`}
                    >
                      {article.isPublished ? "Published" : "Draft"}
                    </span>
                  </div>
                </div>

                <span className="hidden shrink-0 text-xs text-muted-foreground sm:block">
                  {new Date(article.dateCreated).toLocaleDateString("en-IN", {
                    day: "numeric",
                    month: "short",
                    year: "numeric",
                  })}
                </span>

                <div className="flex shrink-0 items-center gap-1.5">
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => onEdit(article)}
                    className="h-8 gap-1.5 rounded-lg px-2.5 text-xs font-medium text-muted-foreground hover:bg-primary/10 hover:text-primary"
                  >
                    <Edit2 className="h-3.5 w-3.5" />
                    <span className="hidden sm:inline">Edit</span>
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => {
                      setSelected(article);
                      setDeleteConfirmOpen(true);
                    }}
                    disabled={isDeleting}
                    className="h-8 gap-1.5 rounded-lg px-2.5 text-xs font-medium text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                  >
                    {isDeleting ? (
                      <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    ) : (
                      <Trash2 className="h-3.5 w-3.5" />
                    )}
                    <span className="hidden sm:inline">Delete</span>
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <AlertDialog open={deleteConfirmOpen} onOpenChange={setDeleteConfirmOpen}>
        <AlertDialogContent className="rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Article?</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete &quot;{selected?.title}&quot;? This
              action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="flex justify-end gap-2 pt-2">
            <AlertDialogCancel className="rounded-full px-5">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmDelete}
              className="rounded-full bg-destructive px-5 text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </div>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

"use client";

import { useState } from "react";
import { Edit2, HeartHandshake, Loader2, Trash2 } from "lucide-react";
import { toast } from "sonner";

import type { FirebaseDonation, FirebaseDonationCampaign } from "@/types/firebase-donation";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { DEFAULT_SONG_COVER } from "@/config/site";
import {
  deleteDonationCampaign,
  setDonationCampaignStatus,
} from "@/lib/donation-campaign-mutations";
import {
  formatDonationAmount,
  getCampaignProgressPercent,
} from "@/lib/donation-firestore";
import { getSongCoverUrl } from "@/lib/utils";

type DonationCampaignListProps = {
  campaigns: FirebaseDonationCampaign[];
  recentDonations: FirebaseDonation[];
  loading: boolean;
  onEdit: (campaign: FirebaseDonationCampaign) => void;
  onDelete: () => void;
};

export function DonationCampaignList({
  campaigns,
  recentDonations,
  loading,
  onEdit,
  onDelete,
}: DonationCampaignListProps) {
  const [deleting, setDeleting] = useState<string | null>(null);
  const [updating, setUpdating] = useState<string | null>(null);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [selected, setSelected] = useState<FirebaseDonationCampaign | null>(null);

  async function handleConfirmDelete() {
    if (!selected) return;
    setDeleting(selected.id);
    try {
      await deleteDonationCampaign(selected.id);
      toast.success("Campaign deleted");
      onDelete();
    } catch {
      toast.error("Failed to delete campaign");
    } finally {
      setDeleting(null);
      setDeleteConfirmOpen(false);
      setSelected(null);
    }
  }

  async function handleToggleStatus(campaign: FirebaseDonationCampaign) {
    setUpdating(campaign.id);
    try {
      const nextStatus = campaign.status === "active" ? "inactive" : "active";
      await setDonationCampaignStatus(campaign.id, nextStatus);
      toast.success(
        nextStatus === "active" ? "Campaign activated" : "Campaign deactivated"
      );
    } catch {
      toast.error("Failed to update campaign status");
    } finally {
      setUpdating(null);
    }
  }

  if (loading) {
    return (
      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        <div className="flex flex-col items-center justify-center gap-3 py-20">
          <Loader2 className="h-7 w-7 animate-spin text-primary/60" />
          <p className="text-sm text-muted-foreground">Loading campaigns…</p>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        <div className="border-b border-border/50 bg-muted/30 px-4 py-3 sm:px-6">
          <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-muted-foreground">
            Campaigns
          </p>
        </div>

        {campaigns.length === 0 ?
          <div className="flex flex-col items-center justify-center gap-3 py-16 text-center">
            <HeartHandshake className="h-5 w-5 text-muted-foreground" />
            <p className="text-sm font-medium">No campaigns have been created for this church yet.</p>
          </div>
        : <div className="divide-y divide-border/40">
            {campaigns.map((campaign) => {
              const coverSrc = getSongCoverUrl(campaign.bannerImage);
              const progress = getCampaignProgressPercent(campaign);

              return (
                <div
                  key={campaign.id}
                  className="flex flex-col gap-4 p-4 sm:flex-row sm:items-center sm:p-5"
                >
                  <img
                    src={coverSrc || DEFAULT_SONG_COVER}
                    alt={campaign.title}
                    className="h-20 w-32 rounded-lg object-cover"
                  />
                  <div className="min-w-0 flex-1 space-y-2">
                    <div className="flex flex-wrap items-center gap-2">
                      <h3 className="font-medium">{campaign.title}</h3>
                      <Badge variant={campaign.status === "active" ? "default" : "secondary"}>
                        {campaign.status}
                      </Badge>
                    </div>
                    <p className="line-clamp-2 text-sm text-muted-foreground">
                      {campaign.description}
                    </p>
                    <p className="text-xs text-muted-foreground">
                      {formatDonationAmount(campaign.currentAmount, campaign.currency)} raised
                      {" · "}
                      {progress}% of{" "}
                      {formatDonationAmount(campaign.targetAmount, campaign.currency)}
                    </p>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <Button
                      size="sm"
                      variant="outline"
                      disabled={updating === campaign.id}
                      onClick={() => handleToggleStatus(campaign)}
                    >
                      {campaign.status === "active" ? "Deactivate" : "Activate"}
                    </Button>
                    <Button size="sm" variant="outline" onClick={() => onEdit(campaign)}>
                      <Edit2 className="mr-1 size-3.5" />
                      Edit
                    </Button>
                    <Button
                      size="sm"
                      variant="destructive"
                      disabled={deleting === campaign.id}
                      onClick={() => {
                        setSelected(campaign);
                        setDeleteConfirmOpen(true);
                      }}
                    >
                      <Trash2 className="mr-1 size-3.5" />
                      Delete
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        }
      </div>

      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        <div className="border-b border-border/50 bg-muted/30 px-4 py-3 sm:px-6">
          <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-muted-foreground">
            Recent Donations
          </p>
        </div>
        {recentDonations.length === 0 ?
          <p className="px-4 py-8 text-center text-sm text-muted-foreground sm:px-6">
            No donations recorded yet.
          </p>
        : <div className="divide-y divide-border/40">
            {recentDonations.map((donation) => (
              <div
                key={donation.id}
                className="flex flex-col gap-1 px-4 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-6"
              >
                <div>
                  <p className="text-sm font-medium">
                    {donation.isAnonymous ? "Anonymous" : donation.donorName}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {donation.paymentStatus} · {donation.paymentProvider}
                  </p>
                </div>
                <p className="text-sm font-semibold">
                  {formatDonationAmount(donation.amount, donation.currency)}
                </p>
              </div>
            ))}
          </div>
        }
      </div>

      <AlertDialog open={deleteConfirmOpen} onOpenChange={setDeleteConfirmOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete campaign?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the campaign. Donation records will remain.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="flex justify-end gap-2">
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmDelete}>Delete</AlertDialogAction>
          </div>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

"use client";

import React, { useState } from "react";
import { CalendarDays, Edit2, Loader2, Trash2 } from "lucide-react";
import { toast } from "sonner";

import type { FirebaseEvent } from "@/types/firebase-event";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { DEFAULT_SONG_COVER } from "@/config/site";
import { formatEventDate } from "@/lib/event-firestore";
import { deleteEvent, updateEvent } from "@/lib/content-mutations-client";
import { notifyIfEventPublished } from "@/lib/notify-if-published";
import { useTenantNotifyFields } from "@/hooks/use-tenant-notify-fields";
import { useFirebaseAuth } from "@/context/firebase-auth-context";
import { getSongCoverUrl } from "@/lib/utils";

type EventListProps = {
  events: FirebaseEvent[];
  loading: boolean;
  onEdit: (event: FirebaseEvent) => void;
  onDelete: () => void;
};

export function EventList({
  events,
  loading,
  onEdit,
  onDelete,
}: EventListProps) {
  const { user } = useFirebaseAuth();
  const tenantFields = useTenantNotifyFields();
  const [deleting, setDeleting] = useState<string | null>(null);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [selected, setSelected] = useState<FirebaseEvent | null>(null);
  const [publishing, setPublishing] = useState<string | null>(null);

  async function handleConfirmDelete() {
    if (!selected) return;
    setDeleting(selected.id);
    try {
      await deleteEvent(selected.id);
      toast.success("Event deleted");
      onDelete();
    } catch {
      toast.error("Failed to delete event");
    } finally {
      setDeleting(null);
      setDeleteConfirmOpen(false);
      setSelected(null);
    }
  }

  async function handlePublish(event: FirebaseEvent) {
    setPublishing(event.id);
    try {
      await updateEvent(event.id, { status: "published" });

      const idToken = user ? await user.getIdToken() : undefined;
      await notifyIfEventPublished({
        contentId: event.id,
        contentTitle: event.title,
        image: event.bannerImage,
        status: "published",
        wasStatus: event.status,
        idToken,
        churchId: event.churchId,
        organizationId: tenantFields.organizationId,
      });

      toast.success("Event published");
    } catch {
      toast.error("Failed to publish event");
    } finally {
      setPublishing(null);
    }
  }

  if (loading) {
    return (
      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        <div className="flex flex-col items-center justify-center gap-3 py-20">
          <Loader2 className="h-7 w-7 animate-spin text-primary/60" />
          <p className="text-sm text-muted-foreground">Loading events…</p>
        </div>
      </div>
    );
  }

  if (events.length === 0) {
    return (
      <div className="overflow-hidden rounded-2xl border border-dashed border-border/60 bg-card/50 shadow-sm">
        <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-muted">
            <CalendarDays className="h-5 w-5 text-muted-foreground" />
          </div>
          <div>
            <p className="text-sm font-medium">No events have been created for this church yet.</p>
            <p className="mt-0.5 text-xs text-muted-foreground">
              Create your first ministry event to get started.
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        <div className="border-b border-border/50 bg-muted/30 px-4 py-3 sm:px-6">
          <div className="flex items-center justify-between">
            <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-muted-foreground">
              All Events
            </p>
            <p className="text-xs text-muted-foreground">
              {events.length} {events.length === 1 ? "event" : "events"}
            </p>
          </div>
        </div>

        <div className="divide-y divide-border/40">
          {events.map((event, index) => {
            const coverSrc = getSongCoverUrl(event.bannerImage);
            const isDeleting = deleting === event.id;
            const isPublishing = publishing === event.id;

            return (
              <div
                key={event.id}
                className="flex items-center gap-3 px-4 py-3 transition-colors hover:bg-accent/30 sm:gap-4 sm:px-6 sm:py-3.5"
              >
                <span className="hidden w-5 shrink-0 text-center text-xs text-muted-foreground/50 sm:block">
                  {index + 1}
                </span>

                <div className="relative h-11 w-16 shrink-0 overflow-hidden rounded-lg border border-border/50 shadow-sm">
                  <img
                    src={coverSrc}
                    alt={event.title}
                    className="h-full w-full object-cover"
                    onError={(e) => {
                      e.currentTarget.src = DEFAULT_SONG_COVER;
                    }}
                  />
                </div>

                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-semibold text-foreground">
                    {event.title}
                  </p>
                  <div className="mt-1 flex flex-wrap items-center gap-1.5">
                    <span className="inline-flex rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-medium text-primary">
                      {event.eventType}
                    </span>
                    <span
                      className={`inline-flex rounded-full px-2 py-0.5 text-[10px] font-medium ${
                        event.status === "published"
                          ? "bg-accent text-muted-foreground"
                          : "bg-muted text-muted-foreground"
                      }`}
                    >
                      {event.status === "published" ? "Published" : "Draft"}
                    </span>
                  </div>
                </div>

                <span className="hidden shrink-0 text-xs text-muted-foreground sm:block">
                  {formatEventDate(event.eventDate)}
                </span>

                <div className="flex shrink-0 items-center gap-1.5">
                  {event.status === "draft" ?
                    <Button
                      size="sm"
                      variant="ghost"
                      disabled={isPublishing}
                      onClick={() => handlePublish(event)}
                      className="h-8 rounded-lg px-2.5 text-xs font-medium text-primary hover:bg-primary/10"
                    >
                      {isPublishing ?
                        <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      : "Publish"}
                    </Button>
                  : null}
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => onEdit(event)}
                    className="h-8 gap-1.5 rounded-lg px-2.5 text-xs font-medium text-muted-foreground hover:bg-primary/10 hover:text-primary"
                  >
                    <Edit2 className="h-3.5 w-3.5" />
                    <span className="hidden sm:inline">Edit</span>
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => {
                      setSelected(event);
                      setDeleteConfirmOpen(true);
                    }}
                    disabled={isDeleting}
                    className="h-8 gap-1.5 rounded-lg px-2.5 text-xs font-medium text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                  >
                    {isDeleting ?
                      <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    : <Trash2 className="h-3.5 w-3.5" />}
                    <span className="hidden sm:inline">Delete</span>
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <AlertDialog open={deleteConfirmOpen} onOpenChange={setDeleteConfirmOpen}>
        <AlertDialogContent className="rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Event?</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete &quot;{selected?.title}&quot;? This
              action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="flex justify-end gap-2 pt-2">
            <AlertDialogCancel className="rounded-full px-5">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmDelete}
              className="rounded-full bg-destructive px-5 text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </div>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

