"use client";

import React, { useState } from "react";
import { Edit2, Trash2, Loader2, Music2, FileText, Headphones, Star, EyeOff } from "lucide-react";
import { toast } from "sonner";

import type { FirebaseSong } from "@/types/firebase-song";
import { DEFAULT_SONG_COVER } from "@/config/site";
import { getSongCoverUrl } from "@/lib/utils";
import {
  getSongAlternateTitle,
  getSongDisplayTitle,
} from "@/lib/song-firestore";

import { Button } from "@/components/ui/button";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { deleteSong } from "@/lib/content-mutations-client";

type MusicListProps = {
  songs: FirebaseSong[];
  loading: boolean;
  onEdit: (song: FirebaseSong) => void;
  onDelete: () => void;
};

export function MusicList({ songs, loading, onEdit, onDelete }: MusicListProps) {
  const [deleting, setDeleting] = useState<string | null>(null);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [selectedSong, setSelectedSong] = useState<FirebaseSong | null>(null);

  function handleDeleteClick(song: FirebaseSong) {
    setSelectedSong(song);
    setDeleteConfirmOpen(true);
  }

  async function handleConfirmDelete() {
    if (!selectedSong) return;
    setDeleting(selectedSong.id);
    try {
      await deleteSong(selectedSong.id);
      toast.success("Song deleted");
      onDelete();
    } catch {
      toast.error("Failed to delete song");
    } finally {
      setDeleting(null);
      setDeleteConfirmOpen(false);
      setSelectedSong(null);
    }
  }

  /* ── Loading ── */
  if (loading) {
    return (
      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        <div className="flex flex-col items-center justify-center gap-3 py-20">
          <Loader2 className="h-7 w-7 animate-spin text-primary/60" />
          <p className="text-sm text-muted-foreground">Loading songs…</p>
        </div>
      </div>
    );
  }

  /* ── Empty ── */
  if (songs.length === 0) {
    return (
      <div className="overflow-hidden rounded-2xl border border-dashed border-border/60 bg-card/50 shadow-sm">
        <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-muted">
            <Music2 className="h-5 w-5 text-muted-foreground" />
          </div>
          <div>
            <p className="text-sm font-medium">No songs have been created for this church yet.</p>
            <p className="mt-0.5 text-xs text-muted-foreground">
              Create your first song to get started.
            </p>
          </div>
        </div>
      </div>
    );
  }

  /* ── List ── */
  return (
    <>
      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        {/* Table header */}
        <div className="border-b border-border/50 bg-muted/30 px-4 py-3 sm:px-6">
          <div className="flex items-center justify-between">
            <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-muted-foreground">
              All Songs
            </p>
            <p className="text-xs text-muted-foreground">
              {songs.length} {songs.length === 1 ? "song" : "songs"}
            </p>
          </div>
        </div>

        {/* Rows */}
        <div className="divide-y divide-border/40">
          {songs.map((song, index) => {
            const coverSrc = getSongCoverUrl(song.imageUrl);
            const hasAudio = !!song.audioUrl?.trim();
            const hasLyrics = !!(song.originalLyrics?.trim() || song.lyrics?.trim());
            const isDeleting = deleting === song.id;
            const displayTitle = getSongDisplayTitle(song);
            const alternateTitle = getSongAlternateTitle(song);

            return (
              <div
                key={song.id}
                className="flex items-center gap-3 px-4 py-3 transition-colors hover:bg-accent/30 sm:gap-4 sm:px-6 sm:py-3.5"
              >
                {/* Index */}
                <span className="hidden w-5 shrink-0 text-center text-xs text-muted-foreground/50 sm:block">
                  {index + 1}
                </span>

                {/* Cover */}
                <div className="relative h-11 w-11 shrink-0 overflow-hidden rounded-lg border border-border/50 shadow-sm">
                  <img
                    src={coverSrc}
                    alt={displayTitle}
                    loading="lazy"
                    decoding="async"
                    className="h-full w-full object-cover"
                    onError={(e) => {
                      e.currentTarget.src = DEFAULT_SONG_COVER;
                    }}
                  />
                </div>

                {/* Title + badges */}
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-semibold text-foreground">
                    {displayTitle}
                  </p>
                  {alternateTitle ? (
                    <p className="truncate text-xs text-muted-foreground">
                      {alternateTitle}
                    </p>
                  ) : null}
                  <div className="mt-1 flex flex-wrap items-center gap-1.5">
                    <span className="rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-medium text-primary">
                      {song.category}
                    </span>
                    {song.featured ? (
                      <span className="inline-flex items-center gap-1 rounded-full bg-amber-500/10 px-2 py-0.5 text-[10px] font-medium text-amber-700 dark:text-amber-400">
                        <Star className="h-2.5 w-2.5" />
                        Featured
                      </span>
                    ) : null}
                    {!song.published ? (
                      <span className="inline-flex items-center gap-1 rounded-full bg-muted px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
                        <EyeOff className="h-2.5 w-2.5" />
                        Draft
                      </span>
                    ) : null}
                    {hasAudio && (
                      <span className="inline-flex items-center gap-1 rounded-full bg-blue-500/10 px-2 py-0.5 text-[10px] font-medium text-blue-600 dark:text-blue-400">
                        <Headphones className="h-2.5 w-2.5" />
                        Audio
                      </span>
                    )}
                    {hasLyrics && (
                      <span className="inline-flex items-center gap-1 rounded-full bg-accent px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
                        <FileText className="h-2.5 w-2.5" />
                        Lyrics
                      </span>
                    )}
                  </div>
                </div>

                {/* Date */}
                <span className="hidden shrink-0 text-xs text-muted-foreground sm:block">
                  {new Date(song.createdAt).toLocaleDateString("en-IN", {
                    day: "numeric",
                    month: "short",
                    year: "numeric",
                  })}
                </span>

                {/* Actions */}
                <div className="flex shrink-0 items-center gap-1.5">
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => onEdit(song)}
                    className="h-8 gap-1.5 rounded-lg px-2.5 text-xs font-medium text-muted-foreground hover:bg-primary/10 hover:text-primary"
                  >
                    <Edit2 className="h-3.5 w-3.5" />
                    <span className="hidden sm:inline">Edit</span>
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => handleDeleteClick(song)}
                    disabled={isDeleting}
                    className="h-8 gap-1.5 rounded-lg px-2.5 text-xs font-medium text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                  >
                    {isDeleting ? (
                      <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    ) : (
                      <Trash2 className="h-3.5 w-3.5" />
                    )}
                    <span className="hidden sm:inline">Delete</span>
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Delete confirm dialog */}
      <AlertDialog open={deleteConfirmOpen} onOpenChange={setDeleteConfirmOpen}>
        <AlertDialogContent className="rounded-2xl">
          <AlertDialogHeader>
            <div className="flex h-11 w-11 items-center justify-center rounded-full bg-destructive/10">
              <Trash2 className="h-5 w-5 text-destructive" />
            </div>
            <AlertDialogTitle className="mt-2">Delete Song?</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete{" "}
              <span className="font-semibold text-foreground">
                &quot;{selectedSong ? getSongDisplayTitle(selectedSong) : ""}&quot;
              </span>
              ? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="flex justify-end gap-2 pt-2">
            <AlertDialogCancel className="rounded-full px-5">
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmDelete}
              className="rounded-full bg-destructive px-5 text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </div>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

"use client";



import { useMemo } from "react";

import { useRouter, useSearchParams } from "next/navigation";



import { RequireAdmin } from "@/components/auth/require-admin";

import { AdminPageHeader } from "@/components/admin/admin-page-header";

import { DonationSettingsPanel } from "@/components/admin/donation-settings-panel";

import { ChurchMembersPanel } from "@/components/church/church-members-panel";

import { ChurchJoinUrlCard } from "@/components/church/church-join-url-card";

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

import { useActiveBranch } from "@/context/active-branch-context";

import { useOrganization } from "@/context/organization-context";

import { adminSectionClass } from "@/lib/responsive-classes";

import { isIndependentChurchWorkspace } from "@/lib/organization/workspace-type";



const CHURCH_SETTINGS_TABS = [

  "general",

  "join-url",

  "donations",

  "members",

] as const;



type ChurchSettingsTab = (typeof CHURCH_SETTINGS_TABS)[number];



function isChurchSettingsTab(value: string | null): value is ChurchSettingsTab {

  return CHURCH_SETTINGS_TABS.includes(value as ChurchSettingsTab);

}



function ChurchSettingsContent() {

  const { churches, organization } = useOrganization();

  const { activeBranch } = useActiveBranch();

  const searchParams = useSearchParams();

  const router = useRouter();

  const isIndependent = isIndependentChurchWorkspace(organization);

  const church = churches[0];

  const churchName = activeBranch?.name ?? church?.name ?? "Your church";



  const activeTab = useMemo(() => {

    const tab = searchParams.get("tab");

    if (tab === "members" && isIndependent) return tab;

    if (tab === "join-url" && isIndependent) return tab;

    if (tab === "donations") return tab;

    return "general";

  }, [searchParams, isIndependent]);



  function handleTabChange(value: string) {

    const query = value === "general" ? "" : `?tab=${value}`;

    router.replace(`/dashboard/church-settings${query}`, { scroll: false });

  }



  return (

    <div className={adminSectionClass}>

      <AdminPageHeader

        title="Church Settings"

        description={

          churchName ?

            `Settings for ${churchName}`

          : "Configure your church profile."

        }

      />



      <Tabs value={activeTab} onValueChange={handleTabChange} className="space-y-6">

        <TabsList className="flex h-auto w-full flex-wrap justify-start gap-1">

          <TabsTrigger value="general">General</TabsTrigger>

          {isIndependent ?

            <TabsTrigger value="join-url">Join URL</TabsTrigger>

          : null}

          <TabsTrigger value="donations">Donation Settings</TabsTrigger>

          {isIndependent ?

            <TabsTrigger value="members">Members</TabsTrigger>

          : null}

        </TabsList>



        <TabsContent value="general" className="space-y-6">

          {churchName ?

            <dl className="grid gap-4 text-sm sm:grid-cols-2">

              <div>

                <dt className="text-muted-foreground">Church name</dt>

                <dd className="font-medium">{churchName}</dd>

              </div>

              <div>

                <dt className="text-muted-foreground">Phone</dt>

                <dd>{church?.phone?.trim() || "—"}</dd>

              </div>

              <div>

                <dt className="text-muted-foreground">Email</dt>

                <dd>{church?.email?.trim() || "—"}</dd>

              </div>

              <div>

                <dt className="text-muted-foreground">Website</dt>

                <dd>{church?.website?.trim() || "—"}</dd>

              </div>

              <div className="sm:col-span-2">

                <dt className="text-muted-foreground">Address</dt>

                <dd>

                  {[

                    church?.address,

                    church?.city,

                    church?.state,

                    church?.country ?? activeBranch?.country ?? organization?.settings?.country,

                  ]

                    .filter(Boolean)

                    .join(", ") || "—"}

                </dd>

              </div>

            </dl>

          : <p className="text-sm text-muted-foreground">No church selected.</p>}

        </TabsContent>



        {isIndependent && activeBranch?.slug && organization ?

          <TabsContent value="join-url">

            <ChurchJoinUrlCard

              organizationId={organization.id}

              branchId={activeBranch.id}

              slug={activeBranch.slug}

              churchName={churchName}

              settings={activeBranch.settings}

              section="join-url"

            />

          </TabsContent>

        : null}



        <TabsContent value="donations">

          <DonationSettingsPanel />

        </TabsContent>



        {isIndependent && activeBranch ?

          <TabsContent value="members" className="space-y-6">

            <ChurchJoinUrlCard

              organizationId={organization!.id}

              branchId={activeBranch.id}

              slug={activeBranch.slug}

              churchName={churchName}

              settings={activeBranch.settings}

              section="enrollment"

            />

            <ChurchMembersPanel

              branchId={activeBranch.id}

              churchName={churchName}

            />

          </TabsContent>

        : null}

      </Tabs>

    </div>

  );

}



export function AdminChurchSettingsPageClient() {

  return (

    <RequireAdmin>

      <ChurchSettingsContent />

    </RequireAdmin>

  );

}

"use client";

import { useEffect, useMemo, useState } from "react";
import dynamic from "next/dynamic";
import { useRouter, useSearchParams } from "next/navigation";
import { Loader2, MapPin, Pencil, Trash2 } from "lucide-react";
import { toast } from "sonner";

import { RequireAdmin } from "@/components/auth/require-admin";
import { AdminListPagination } from "@/components/admin/admin-list-pagination";
import { AdminPageHeader } from "@/components/admin/admin-page-header";
import { AdminToolbar } from "@/components/admin/admin-toolbar";
import { PlanBadge } from "@/components/subscription/plan-badge";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { useFirebaseAuth } from "@/context/firebase-auth-context";
import { useOrganization } from "@/context/organization-context";
import { filterBySearch, paginateItems } from "@/lib/admin-list-utils";
import { isIndependentChurchWorkspace } from "@/lib/organization/workspace-type";
import {
  deleteBranchAction,
  updateBranchAction,
  updateOrganizationAction,
} from "@/lib/organization/organization-mutations";
import { OrganizationInvitationsPanel } from "@/components/organization/organization-invitations-panel";
import { OrganizationMembersPanel } from "@/components/organization/organization-members-panel";
import { adminSectionClass } from "@/lib/responsive-classes";
import type { FirebaseBranch } from "@/types/branch";

const AddChurchModal = dynamic(
  () =>
    import("@/components/admin/add-church-modal").then((mod) => mod.AddChurchModal),
  { ssr: false }
);

const BranchModal = dynamic(
  () =>
    import("@/components/admin/organization/branch-modal").then(
      (mod) => mod.BranchModal
    ),
  { ssr: false }
);

function OrganizationSettingsForm() {
  const { authUser } = useFirebaseAuth();
  const { organization, loading, refetch } = useOrganization();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [logo, setLogo] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!organization) return;
    setName(organization.name);
    setDescription(organization.description ?? "");
    setLogo(organization.logo ?? "");
  }, [organization]);

  async function handleSave(event: React.FormEvent) {
    event.preventDefault();
    if (!organization || !authUser) return;

    setSaving(true);
    try {
      await updateOrganizationAction(
        organization.id,
        authUser.uid,
        authUser.email,
        {
          name: name.trim(),
          description: description.trim() || undefined,
          logo: logo.trim() || undefined,
        }
      );
      toast.success("Organization settings saved");
      refetch();
    } catch {
      toast.error("Failed to save organization settings");
    } finally {
      setSaving(false);
    }
  }

  if (loading && !organization) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="size-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!organization) {
    return (
      <Card>
        <CardContent className="py-10 text-center text-sm text-muted-foreground">
          No organization found for your account.
        </CardContent>
      </Card>
    );
  }

  return (
    <form onSubmit={handleSave} className="space-y-6">
      <Card>
        <CardHeader>
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div>
              <CardTitle>Organization Profile</CardTitle>
              <CardDescription>
                Identity and branding for your organization tenant.
              </CardDescription>
            </div>
            <PlanBadge planId={organization.subscriptionPlan} />
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="org-name">Organization name</Label>
            <Input
              id="org-name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="org-description">Description</Label>
            <Textarea
              id="org-description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={4}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="org-logo">Logo URL</Label>
            <Input
              id="org-logo"
              value={logo}
              onChange={(e) => setLogo(e.target.value)}
              placeholder="https://..."
            />
          </div>
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            <span>Status</span>
            <Badge variant="secondary">{organization.status}</Badge>
          </div>
        </CardContent>
      </Card>

      <div className="flex justify-end">
        <Button type="submit" disabled={saving}>
          {saving ?
            <>
              <Loader2 className="mr-2 size-4 animate-spin" />
              Saving…
            </>
          : "Save settings"}
        </Button>
      </div>
    </form>
  );
}

function OrganizationChurchesPanel() {
  const { authUser } = useFirebaseAuth();
  const { organization, churches, branchesByChurch, loading, refetch } =
    useOrganization();
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [modalOpen, setModalOpen] = useState(false);
  const [branchModalOpen, setBranchModalOpen] = useState(false);
  const [editingBranch, setEditingBranch] = useState<FirebaseBranch | null>(
    null
  );
  const [busyBranchId, setBusyBranchId] = useState<string | null>(null);

  const allChurches = useMemo(
    () => Object.values(branchesByChurch).flat(),
    [branchesByChurch]
  );

  const filteredChurches = useMemo(
    () =>
      filterBySearch(allChurches, search, (branch) =>
        [branch.name, branch.slug, branch.city, branch.country]
          .filter(Boolean)
          .join(" ")
      ),
    [allChurches, search]
  );

  const { pageItems, totalPages, safePage } = useMemo(
    () => paginateItems(filteredChurches, page),
    [filteredChurches, page]
  );

  async function handleDeleteChurch(branchId: string) {
    if (!organization || !authUser) return;
    setBusyBranchId(branchId);
    try {
      await deleteBranchAction(
        organization.id,
        branchId,
        authUser.uid,
        authUser.email
      );
      toast.success("Church deleted");
      refetch();
    } catch {
      toast.error("Failed to delete church");
    } finally {
      setBusyBranchId(null);
    }
  }

  return (
    <div className="space-y-4">
      <AdminPageHeader
        title="Churches"
        description="Create and manage churches in your organization."
        actionLabel="Create Church"
        onAction={() => {
          setEditingBranch(null);
          setModalOpen(true);
        }}
      />

      <AdminToolbar
        search={search}
        onSearchChange={setSearch}
        searchPlaceholder="Search churches…"
      />

      {pageItems.length === 0 && !loading ?
        <Card>
          <CardContent className="py-10 text-center text-sm text-muted-foreground">
            No churches yet. Create your first church to start inviting admins
            and managing content.
          </CardContent>
        </Card>
      : <div className="space-y-3">
          {pageItems.map((branch) => (
            <Card key={branch.id}>
              <CardContent className="flex flex-col gap-3 py-4 sm:flex-row sm:items-center sm:justify-between">
                <div className="min-w-0 space-y-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="font-medium">{branch.name}</p>
                    <Badge variant={branch.isActive ? "default" : "secondary"}>
                      {branch.isActive ? "Active" : "Inactive"}
                    </Badge>
                  </div>
                  {branch.address || branch.city ?
                    <p className="flex items-center gap-1 text-xs text-muted-foreground">
                      <MapPin className="size-3" />
                      {[branch.address, branch.city, branch.state, branch.country]
                        .filter(Boolean)
                        .join(", ")}
                    </p>
                  : null}
                </div>
                <div className="flex shrink-0 gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      setEditingBranch(branch);
                      setBranchModalOpen(true);
                    }}
                  >
                    <Pencil className="mr-1 size-3.5" />
                    Edit
                  </Button>
                  <Button
                    type="button"
                    variant="destructive"
                    size="sm"
                    disabled={busyBranchId === branch.id}
                    onClick={() => void handleDeleteChurch(branch.id)}
                  >
                    <Trash2 className="size-3.5" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      }

      <AdminListPagination
        page={safePage}
        totalPages={totalPages}
        totalItems={filteredChurches.length}
        onPageChange={setPage}
      />

      {organization && authUser ?
        <>
          <AddChurchModal
            isOpen={modalOpen}
            onClose={() => setModalOpen(false)}
            onSave={() => {
              setModalOpen(false);
              refetch();
            }}
            organizationId={organization.id}
            userId={authUser.uid}
            userEmail={authUser.email}
          />
          {editingBranch ?
            <BranchModal
              isOpen={branchModalOpen}
              onClose={() => {
                setBranchModalOpen(false);
                setEditingBranch(null);
              }}
              onSave={() => {
                setBranchModalOpen(false);
                setEditingBranch(null);
                refetch();
              }}
              organizationId={organization.id}
              churchId={editingBranch.churchId}
              userId={authUser.uid}
              userEmail={authUser.email}
              initialBranch={editingBranch}
            />
          : null}
        </>
      : null}
    </div>
  );
}

export function OrganizationBranchesPanel() {
  const { authUser } = useFirebaseAuth();
  const { organization, churches, branchesByChurch, loading, refetch } =
    useOrganization();
  const [selectedChurchId, setSelectedChurchId] = useState<string>("");
  const [branchModalOpen, setBranchModalOpen] = useState(false);
  const [editingBranch, setEditingBranch] = useState<FirebaseBranch | null>(
    null
  );
  const [busyBranchId, setBusyBranchId] = useState<string | null>(null);

  const activeChurches = churches.filter((c) => c.isActive);

  useEffect(() => {
    if (!selectedChurchId && activeChurches[0]) {
      setSelectedChurchId(activeChurches[0].id);
    }
  }, [activeChurches, selectedChurchId]);

  const branches = selectedChurchId ?
    (branchesByChurch[selectedChurchId] ?? [])
  : [];

  async function handleDeleteBranch(branchId: string) {
    if (!organization || !authUser) return;
    setBusyBranchId(branchId);
    try {
      await deleteBranchAction(
        organization.id,
        branchId,
        authUser.uid,
        authUser.email
      );
      toast.success("Church deleted");
      refetch();
    } catch {
      toast.error("Failed to delete church");
    } finally {
      setBusyBranchId(null);
    }
  }

  async function handleToggleBranch(branch: FirebaseBranch) {
    if (!organization || !authUser) return;
    setBusyBranchId(branch.id);
    try {
      await updateBranchAction(
        organization.id,
        branch.id,
        authUser.uid,
        authUser.email,
        { isActive: !branch.isActive }
      );
      toast.success(branch.isActive ? "Church disabled" : "Church activated");
      refetch();
    } catch {
      toast.error("Failed to update church");
    } finally {
      setBusyBranchId(null);
    }
  }

  if (loading && !organization) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="size-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (activeChurches.length === 0) {
    return (
      <Card>
        <CardContent className="py-10 text-center text-sm text-muted-foreground">
          Add a church first before creating branches. Branches are optional —
          single-location churches work without them.
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      <AdminPageHeader
        title="Churches"
        description="Manage churches in your organization."
        actionLabel="Create Church"
        onAction={() => {
          setEditingBranch(null);
          setBranchModalOpen(true);
        }}
      />

      <div className="max-w-xs space-y-2">
        <Label>Church</Label>
        <Select value={selectedChurchId} onValueChange={setSelectedChurchId}>
          <SelectTrigger>
            <SelectValue placeholder="Select church" />
          </SelectTrigger>
          <SelectContent>
            {activeChurches.map((church) => (
              <SelectItem key={church.id} value={church.id}>
                {church.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {branches.length === 0 ?
        <Card>
          <CardContent className="py-10 text-center text-sm text-muted-foreground">
            No branches for this church. Branches are optional — your church
            can operate as a single location.
          </CardContent>
        </Card>
      : <div className="space-y-3">
          {branches.map((branch) => (
            <Card key={branch.id}>
              <CardContent className="flex flex-col gap-3 py-4 sm:flex-row sm:items-center sm:justify-between">
                <div className="min-w-0 space-y-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="font-medium">{branch.name}</p>
                    <Badge variant={branch.isActive ? "default" : "secondary"}>
                      {branch.isActive ? "Active" : "Inactive"}
                    </Badge>
                  </div>
                  {branch.address || branch.city ?
                    <p className="flex items-center gap-1 text-xs text-muted-foreground">
                      <MapPin className="size-3" />
                      {[branch.address, branch.city, branch.state, branch.country]
                        .filter(Boolean)
                        .join(", ")}
                    </p>
                  : null}
                </div>
                <div className="flex shrink-0 gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      setEditingBranch(branch);
                      setBranchModalOpen(true);
                    }}
                  >
                    <Pencil className="mr-1 size-3.5" />
                    Edit
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    disabled={busyBranchId === branch.id}
                    onClick={() => void handleToggleBranch(branch)}
                  >
                    {branch.isActive ? "Disable" : "Enable"}
                  </Button>
                  <Button
                    type="button"
                    variant="destructive"
                    size="sm"
                    disabled={busyBranchId === branch.id}
                    onClick={() => void handleDeleteBranch(branch.id)}
                  >
                    <Trash2 className="size-3.5" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      }

      {organization && authUser && selectedChurchId ?
        <BranchModal
          isOpen={branchModalOpen}
          onClose={() => {
            setBranchModalOpen(false);
            setEditingBranch(null);
          }}
          onSave={() => {
            setBranchModalOpen(false);
            setEditingBranch(null);
            refetch();
          }}
          organizationId={organization.id}
          churchId={selectedChurchId}
          userId={authUser.uid}
          userEmail={authUser.email}
          initialBranch={editingBranch}
        />
      : null}
    </div>
  );
}

function OrganizationPageContent() {
  const { organization } = useOrganization();
  const searchParams = useSearchParams();
  const router = useRouter();
  const isIndependent = isIndependentChurchWorkspace(organization);

  const tabParam = searchParams.get("tab");
  const activeTab = useMemo(() => {
    const allowed = new Set(["settings"]);
    if (!isIndependent) {
      allowed.add("churches");
      allowed.add("invitations");
      allowed.add("members");
      allowed.add("roles");
    }
    if (tabParam && allowed.has(tabParam)) return tabParam;
    return "settings";
  }, [tabParam, isIndependent]);

  function handleTabChange(value: string) {
    router.replace(`/dashboard/organization?tab=${value}`, { scroll: false });
  }

  return (
    <div className={adminSectionClass}>
      <AdminPageHeader
        title="Organization"
        description="Manage your organization, churches, members, and invitations."
      />

      <Tabs value={activeTab} onValueChange={handleTabChange} className="space-y-6">
        <TabsList className="flex h-auto flex-wrap">
          <TabsTrigger value="settings">General</TabsTrigger>
          {!isIndependent ?
            <>
              <TabsTrigger value="churches">Churches</TabsTrigger>
              <TabsTrigger value="invitations">Invitations</TabsTrigger>
              <TabsTrigger value="members">Members</TabsTrigger>
              <TabsTrigger value="roles">Roles & Permissions</TabsTrigger>
            </>
          : null}
          <TabsTrigger value="billing" asChild>
            <a href="/dashboard/billing">Billing</a>
          </TabsTrigger>
        </TabsList>

        <TabsContent value="settings">
          <OrganizationSettingsForm />
        </TabsContent>
        {!isIndependent ?
          <>
            <TabsContent value="churches">
              <OrganizationChurchesPanel />
            </TabsContent>
            <TabsContent value="invitations">
              <OrganizationInvitationsPanel />
            </TabsContent>
            <TabsContent value="members">
              <OrganizationMembersPanel />
            </TabsContent>
            <TabsContent value="roles">
              <OrganizationMembersPanel />
            </TabsContent>
          </>
        : null}
      </Tabs>
    </div>
  );
}

export function AdminOrganizationPageClient() {
  return (
    <RequireAdmin>
      <OrganizationPageContent />
    </RequireAdmin>
  );
}

"use client";

import React, { useState } from "react";
import { Edit2, Loader2, Trash2, Church } from "lucide-react";
import { toast } from "sonner";

import type { FirebaseSermon } from "@/types/firebase-sermon";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { DEFAULT_SONG_COVER } from "@/config/site";
import { deleteSermon } from "@/lib/content-mutations-client";
import { getSongCoverUrl } from "@/lib/utils";

type SermonListProps = {
  sermons: FirebaseSermon[];
  loading: boolean;
  onEdit: (sermon: FirebaseSermon) => void;
  onDelete: () => void;
};

export function SermonList({
  sermons,
  loading,
  onEdit,
  onDelete,
}: SermonListProps) {
  const [deleting, setDeleting] = useState<string | null>(null);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [selected, setSelected] = useState<FirebaseSermon | null>(null);

  async function handleConfirmDelete() {
    if (!selected) return;
    setDeleting(selected.id);
    try {
      await deleteSermon(selected.id);
      toast.success("Sermon deleted");
      onDelete();
    } catch {
      toast.error("Failed to delete sermon");
    } finally {
      setDeleting(null);
      setDeleteConfirmOpen(false);
      setSelected(null);
    }
  }

  if (loading) {
    return (
      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        <div className="flex flex-col items-center justify-center gap-3 py-20">
          <Loader2 className="h-7 w-7 animate-spin text-primary/60" />
          <p className="text-sm text-muted-foreground">Loading sermons…</p>
        </div>
      </div>
    );
  }

  if (sermons.length === 0) {
    return (
      <div className="overflow-hidden rounded-2xl border border-dashed border-border/60 bg-card/50 shadow-sm">
        <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-muted">
            <Church className="h-5 w-5 text-muted-foreground" />
          </div>
          <div>
            <p className="text-sm font-medium">No sermons have been created for this church yet.</p>
            <p className="mt-0.5 text-xs text-muted-foreground">
              Add your first sermon to get started.
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="overflow-hidden rounded-2xl border border-border/50 bg-card shadow-sm">
        <div className="border-b border-border/50 bg-muted/30 px-4 py-3 sm:px-6">
          <div className="flex items-center justify-between">
            <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-muted-foreground">
              All Sermons
            </p>
            <p className="text-xs text-muted-foreground">
              {sermons.length}{" "}
              {sermons.length === 1 ? "sermon" : "sermons"}
            </p>
          </div>
        </div>

        <div className="divide-y divide-border/40">
          {sermons.map((sermon, index) => {
            const coverSrc = getSongCoverUrl(sermon.coverImage);
            const isDeleting = deleting === sermon.id;

            return (
              <div
                key={sermon.id}
                className="flex items-center gap-3 px-4 py-3 transition-colors hover:bg-accent/30 sm:gap-4 sm:px-6 sm:py-3.5"
              >
                <span className="hidden w-5 shrink-0 text-center text-xs text-muted-foreground/50 sm:block">
                  {index + 1}
                </span>

                <div className="relative h-11 w-11 shrink-0 overflow-hidden rounded-lg border border-border/50 shadow-sm">
                  <img
                    src={coverSrc}
                    alt={sermon.title}
                    className="h-full w-full object-cover"
                    onError={(e) => {
                      e.currentTarget.src = DEFAULT_SONG_COVER;
                    }}
                  />
                </div>

                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-semibold text-foreground">
                    {sermon.title}
                  </p>
                  <div className="mt-1 flex items-center gap-1.5">
                    <span className="inline-flex rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-medium text-primary">
                      {sermon.scriptureReference || sermon.speaker || "Sermon"}
                    </span>
                    <span
                      className={`inline-flex rounded-full px-2 py-0.5 text-[10px] font-medium ${
                        sermon.isPublished
                          ? "bg-accent text-muted-foreground"
                          : "bg-muted text-muted-foreground"
                      }`}
                    >
                      {sermon.isPublished ? "Published" : "Draft"}
                    </span>
                  </div>
                </div>

                <span className="hidden shrink-0 text-xs text-muted-foreground sm:block">
                  {new Date(sermon.dateCreated).toLocaleDateString("en-IN", {
                    day: "numeric",
                    month: "short",
                    year: "numeric",
                  })}
                </span>

                <div className="flex shrink-0 items-center gap-1.5">
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => onEdit(sermon)}
                    className="h-8 gap-1.5 rounded-lg px-2.5 text-xs font-medium text-muted-foreground hover:bg-primary/10 hover:text-primary"
                  >
                    <Edit2 className="h-3.5 w-3.5" />
                    <span className="hidden sm:inline">Edit</span>
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => {
                      setSelected(sermon);
                      setDeleteConfirmOpen(true);
                    }}
                    disabled={isDeleting}
                    className="h-8 gap-1.5 rounded-lg px-2.5 text-xs font-medium text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                  >
                    {isDeleting ? (
                      <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    ) : (
                      <Trash2 className="h-3.5 w-3.5" />
                    )}
                    <span className="hidden sm:inline">Delete</span>
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <AlertDialog open={deleteConfirmOpen} onOpenChange={setDeleteConfirmOpen}>
        <AlertDialogContent className="rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Sermon?</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete &quot;{selected?.title}&quot;? This
              action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="flex justify-end gap-2 pt-2">
            <AlertDialogCancel className="rounded-full px-5">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmDelete}
              className="rounded-full bg-destructive px-5 text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </div>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

"use client";

import Link from "next/link";
import { usePathname, useSearchParams } from "next/navigation";
import { ChevronRight } from "lucide-react";
import { useEffect, useState } from "react";

import { getChurchManagementNavItems } from "@/lib/organization/church-management-nav";
import {
  CHURCH_MANAGEMENT_GROUP_ICON,
  CHURCH_MANAGEMENT_GROUP_LABEL,
  isChurchManagementPath,
} from "@/config/church-management-nav";
import { useOrganizationOptional } from "@/context/organization-context";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  useSidebar,
} from "@/components/ui/sidebar";
import { cn } from "@/lib/utils";

const STORAGE_KEY = "sidebar_church_management_open";

export function NavChurchManagement() {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const { isMobile, setOpenMobile } = useSidebar();
  const GroupIcon = CHURCH_MANAGEMENT_GROUP_ICON;

  const [open, setOpen] = useState(true);
  const [hydrated, setHydrated] = useState(false);

  useEffect(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored === "false") setOpen(false);
      else if (stored === "true") setOpen(true);
      else if (isChurchManagementPath(pathname)) setOpen(true);
    } catch {
      // ignore
    }
    setHydrated(true);
  }, [pathname]);

  useEffect(() => {
    if (!hydrated) return;
    try {
      localStorage.setItem(STORAGE_KEY, String(open));
    } catch {
      // ignore
    }
  }, [open, hydrated]);

  useEffect(() => {
    if (isChurchManagementPath(pathname)) {
      setOpen(true);
    }
  }, [pathname]);

  const organization = useOrganizationOptional()?.organization;
  const navItems = getChurchManagementNavItems(organization);

  const groupActive = navItems.some((item) =>
    item.match(pathname, searchParams)
  );

  function closeMobile() {
    if (isMobile) setOpenMobile(false);
  }

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="group/collapsible">
      <SidebarMenuItem>
        <CollapsibleTrigger asChild>
          <SidebarMenuButton
            tooltip={CHURCH_MANAGEMENT_GROUP_LABEL}
            isActive={groupActive}
            className="font-medium"
          >
            <GroupIcon />
            <span>{CHURCH_MANAGEMENT_GROUP_LABEL}</span>
            <ChevronRight
              className={cn(
                "ml-auto size-4 shrink-0 text-muted-foreground transition-transform duration-200",
                open && "rotate-90"
              )}
            />
          </SidebarMenuButton>
        </CollapsibleTrigger>
        <CollapsibleContent className="overflow-hidden data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down">
          <SidebarMenuSub>
            {navItems.map((item) => {
              const Icon = item.icon;
              const isActive = item.match(pathname, searchParams);

              return (
                <SidebarMenuSubItem key={item.href}>
                  <SidebarMenuSubButton asChild isActive={isActive}>
                    <Link href={item.href} onClick={closeMobile}>
                      <Icon className="size-4" />
                      <span>{item.label}</span>
                    </Link>
                  </SidebarMenuSubButton>
                </SidebarMenuSubItem>
              );
            })}
          </SidebarMenuSub>
        </CollapsibleContent>
      </SidebarMenuItem>
    </Collapsible>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { usePathname, useRouter } from "next/navigation";

import { useFirebaseAuth } from "@/context/firebase-auth-context";
import { useMembershipRouting } from "@/hooks/use-membership-routing";
import { useMembershipRealtimeSync } from "@/hooks/use-membership-realtime-sync";
import {
  ACCESS_DENIED_PATH,
  ACCOUNT_SUSPENDED_PATH,
  isInvitePath,
  isJoinPath,
  isOnboardingPath,
  isSuperAdminPath,
  isWaitingApprovalPath,
  MEMBERSHIP_REMOVED_PATH,
  ORGANIZATION_SUSPENDED_PATH,
  WAITING_APPROVAL_PATH,
} from "@/lib/auth/auth-paths";

const AUTH_PATHS = new Set([
  "/signin",
  "/signup",
  "/forgot-password",
]);

function isExemptMembershipPath(pathname: string): boolean {
  if (AUTH_PATHS.has(pathname)) return true;
  if (isOnboardingPath(pathname)) return true;
  if (isJoinPath(pathname)) return true;
  if (isInvitePath(pathname)) return true;
  if (isSuperAdminPath(pathname)) return true;
  if (pathname === ACCESS_DENIED_PATH) return true;
  if (pathname === MEMBERSHIP_REMOVED_PATH) return true;
  if (pathname === ACCOUNT_SUSPENDED_PATH) return true;
  if (pathname === ORGANIZATION_SUSPENDED_PATH) return true;
  return false;
}

/**
 * Redirects members based on branch membership status on every navigation.
 */
export function MembershipStatusGuard() {
  const router = useRouter();
  const pathname = usePathname();
  const { authUser, loading: authLoading, profileReady } = useFirebaseAuth();
  const { routing, loading: routingLoading } = useMembershipRouting();
  const redirectingRef = useRef(false);

  useMembershipRealtimeSync();

  useEffect(() => {
    redirectingRef.current = false;
  }, [pathname]);

  useEffect(() => {
    if (!authUser || authLoading || !profileReady || routingLoading || !routing) return;
    if (redirectingRef.current) return;

    const { status, destination } = routing;

    if (status === "pending") {
      if (!isWaitingApprovalPath(pathname) && !isExemptMembershipPath(pathname)) {
        redirectingRef.current = true;
        router.replace(WAITING_APPROVAL_PATH);
      }
      return;
    }

    if (isWaitingApprovalPath(pathname)) {
      if (status === "active") {
        return;
      }
      if (status === "rejected") {
        redirectingRef.current = true;
        router.replace(ACCESS_DENIED_PATH);
        return;
      }
      if (status === "removed") {
        redirectingRef.current = true;
        router.replace(MEMBERSHIP_REMOVED_PATH);
        return;
      }
      if (status === "suspended") {
        redirectingRef.current = true;
        router.replace(ACCOUNT_SUSPENDED_PATH);
        return;
      }
      if (status === "org_suspended") {
        redirectingRef.current = true;
        router.replace(ORGANIZATION_SUSPENDED_PATH);
        return;
      }
    }

    if (status === "rejected" && pathname !== ACCESS_DENIED_PATH) {
      redirectingRef.current = true;
      router.replace(ACCESS_DENIED_PATH);
      return;
    }

    if (status === "removed" && pathname !== MEMBERSHIP_REMOVED_PATH) {
      redirectingRef.current = true;
      router.replace(MEMBERSHIP_REMOVED_PATH);
      return;
    }

    if (status === "suspended" && pathname !== ACCOUNT_SUSPENDED_PATH) {
      redirectingRef.current = true;
      router.replace(ACCOUNT_SUSPENDED_PATH);
      return;
    }

    if (status === "org_suspended" && pathname !== ORGANIZATION_SUSPENDED_PATH) {
      redirectingRef.current = true;
      router.replace(ORGANIZATION_SUSPENDED_PATH);
    }
  }, [
    authUser,
    authLoading,
    profileReady,
    routingLoading,
    routing,
    pathname,
    router,
  ]);

  return null;
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { format } from "date-fns";
import { Loader2, UserCheck, UserX } from "lucide-react";
import { toast } from "sonner";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { useOrganization } from "@/context/organization-context";
import { firebaseAuth } from "@/lib/firebase-auth-service";
import type { FirebaseBranchMembership } from "@/types/branch-membership";

type BranchMembersResponse = {
  pending: FirebaseBranchMembership[];
  active: FirebaseBranchMembership[];
  usersById: Record<
    string,
    {
      email: string;
      firstName: string;
      lastName: string;
      photoURL?: string;
    }
  >;
};

type ChurchMembersPanelProps = {
  branchId: string;
  churchName?: string;
};

function formatRequestedDate(timestamp: number): string {
  if (!timestamp) return "—";
  return format(new Date(timestamp), "MMM d, yyyy");
}

function memberInitials(
  user?: { firstName: string; lastName: string; email: string }
): string {
  if (!user) return "?";
  const fromName = `${user.firstName?.[0] ?? ""}${user.lastName?.[0] ?? ""}`
    .trim()
    .toUpperCase();
  if (fromName) return fromName;
  return user.email?.[0]?.toUpperCase() ?? "?";
}

function memberName(
  userId: string,
  usersById: BranchMembersResponse["usersById"]
): string {
  const user = usersById[userId];
  if (!user) return userId;
  const name = `${user.firstName} ${user.lastName}`.trim();
  return name || user.email || userId;
}

export function ChurchMembersPanel({
  branchId,
  churchName,
}: ChurchMembersPanelProps) {
  const { organization } = useOrganization();
  const [data, setData] = useState<BranchMembersResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const load = useCallback(async () => {
    if (!organization) return;
    const user = firebaseAuth.currentUser;
    if (!user) return;

    setLoading(true);
    try {
      const token = await user.getIdToken();
      const res = await fetch(
        `/api/memberships/branch?organizationId=${encodeURIComponent(organization.id)}&branchId=${encodeURIComponent(branchId)}`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        toast.error(body.error ?? "Failed to load members");
        return;
      }
      setData((await res.json()) as BranchMembersResponse);
      setSelectedIds(new Set());
    } finally {
      setLoading(false);
    }
  }, [organization, branchId]);

  useEffect(() => {
    void load();
  }, [load]);

  const pending = data?.pending ?? [];
  const active = data?.active ?? [];
  const usersById = data?.usersById ?? {};

  const allPendingSelected = useMemo(
    () => pending.length > 0 && pending.every((m) => selectedIds.has(m.id)),
    [pending, selectedIds]
  );

  function toggleSelect(membershipId: string) {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(membershipId)) next.delete(membershipId);
      else next.add(membershipId);
      return next;
    });
  }

  function toggleSelectAllPending() {
    if (allPendingSelected) {
      setSelectedIds(new Set());
      return;
    }
    setSelectedIds(new Set(pending.map((m) => m.id)));
  }

  async function review(
    membershipIds: string[],
    action: "approve" | "reject"
  ) {
    if (!organization || !membershipIds.length) return;
    const user = firebaseAuth.currentUser;
    if (!user) return;

    setBusy(true);
    try {
      const token = await user.getIdToken();
      const res = await fetch("/api/memberships/pending", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          organizationId: organization.id,
          membershipIds,
          action,
        }),
      });
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        throw new Error(body.error ?? "Failed to update members");
      }
      toast.success(
        action === "approve" ?
          membershipIds.length > 1 ?
            `${membershipIds.length} members approved`
          : "Member approved"
        : membershipIds.length > 1 ?
          `${membershipIds.length} requests rejected`
        : "Request rejected"
      );
      await load();
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : "Failed to update members"
      );
    } finally {
      setBusy(false);
    }
  }

  function renderMemberRow(
    member: FirebaseBranchMembership,
    options?: { showActions?: boolean; selectable?: boolean }
  ) {
    const user = usersById[member.userId];
    const name = memberName(member.userId, usersById);

    return (
      <li
        key={member.id}
        className="flex flex-col gap-3 rounded-xl border border-border/50 p-4 sm:flex-row sm:items-center sm:justify-between"
      >
        <div className="flex min-w-0 items-center gap-3">
          {options?.selectable ?
            <input
              type="checkbox"
              className="size-4 shrink-0 rounded border-input"
              checked={selectedIds.has(member.id)}
              onChange={() => toggleSelect(member.id)}
              aria-label={`Select ${name}`}
            />
          : null}
          <Avatar className="size-10">
            {user?.photoURL ?
              <AvatarImage src={user.photoURL} alt="" />
            : null}
            <AvatarFallback>{memberInitials(user)}</AvatarFallback>
          </Avatar>
          <div className="min-w-0">
            <p className="truncate font-medium">{name}</p>
            <p className="truncate text-sm text-muted-foreground">
              {user?.email ?? "—"}
            </p>
            <p className="text-xs text-muted-foreground">
              Requested {formatRequestedDate(member.createdAt)}
            </p>
          </div>
        </div>
        {options?.showActions ?
          <div className="flex shrink-0 gap-2 sm:ml-auto">
            <Button
              size="sm"
              disabled={busy}
              onClick={() => void review([member.id], "approve")}
            >
              {busy ?
                <Loader2 className="mr-1.5 size-4 animate-spin" />
              : <UserCheck className="mr-1.5 size-4" />}
              Approve
            </Button>
            <Button
              size="sm"
              variant="outline"
              disabled={busy}
              onClick={() => void review([member.id], "reject")}
            >
              {busy ?
                <Loader2 className="mr-1.5 size-4 animate-spin" />
              : <UserX className="mr-1.5 size-4" />}
              Reject
            </Button>
          </div>
        : null}
      </li>
    );
  }

  if (loading) {
    return (
      <div className="flex justify-center py-16">
        <Loader2 className="size-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Pending requests</CardTitle>
          <CardDescription>
            {churchName ?
              `People who requested to join ${churchName} via your join link.`
            : "Approve requests to grant access to church content."}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {pending.length > 0 ?
            <>
              <div className="flex flex-wrap items-center gap-2">
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  onClick={toggleSelectAllPending}
                >
                  {allPendingSelected ? "Clear selection" : "Select all"}
                </Button>
                <Button
                  type="button"
                  size="sm"
                  disabled={busy || selectedIds.size === 0}
                  onClick={() =>
                    void review(Array.from(selectedIds), "approve")
                  }
                >
                  Bulk approve
                </Button>
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  disabled={busy || selectedIds.size === 0}
                  onClick={() =>
                    void review(Array.from(selectedIds), "reject")
                  }
                >
                  Bulk reject
                </Button>
              </div>
              <ul className="space-y-3">
                {pending.map((member) =>
                  renderMemberRow(member, {
                    showActions: true,
                    selectable: true,
                  })
                )}
              </ul>
            </>
          : <p className="text-sm text-muted-foreground">
              No pending requests right now.
            </p>
          }
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base">Approved members</CardTitle>
          <CardDescription>
            Active members with access to this church workspace.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {active.length > 0 ?
            <ul className="space-y-3">
              {active.map((member) => {
                const user = usersById[member.userId];
                const name = memberName(member.userId, usersById);
                return (
                  <li
                    key={member.id}
                    className="flex items-center gap-3 rounded-xl border border-border/50 p-4"
                  >
                    <Avatar className="size-10">
                      {user?.photoURL ?
                        <AvatarImage src={user.photoURL} alt="" />
                      : null}
                      <AvatarFallback>{memberInitials(user)}</AvatarFallback>
                    </Avatar>
                    <div className="min-w-0">
                      <p className="truncate font-medium">{name}</p>
                      <p className="truncate text-sm text-muted-foreground">
                        {user?.email ?? "—"}
                      </p>
                    </div>
                  </li>
                );
              })}
            </ul>
          : <p className="text-sm text-muted-foreground">
              No approved members yet. Share your join link to get started.
            </p>
          }
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { CheckCircle2, Loader2, Ticket } from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { useFirebaseAuth } from "@/context/firebase-auth-context";
import { hasRegisteredForEvent } from "@/lib/event-registration-actions";

type RegisterForEventButtonProps = {
  eventId: string;
  eventTitle: string;
};

export function RegisterForEventButton({
  eventId,
  eventTitle,
}: RegisterForEventButtonProps) {
  const { authUser, profile, loading, user } = useFirebaseAuth();
  const [registering, setRegistering] = useState(false);
  const [registered, setRegistered] = useState(false);
  const [checkingRegistration, setCheckingRegistration] = useState(false);

  useEffect(() => {
    if (!user?.uid || !eventId) {
      setCheckingRegistration(false);
      return;
    }

    let cancelled = false;
    setCheckingRegistration(true);

    async function loadExistingRegistration() {
      try {
        const exists = await hasRegisteredForEvent(eventId, user!.uid);
        if (!cancelled && exists) {
          setRegistered(true);
        }
      } catch {
        // Ignore lookup errors — user can still attempt registration.
      } finally {
        if (!cancelled) {
          setCheckingRegistration(false);
        }
      }
    }

    void loadExistingRegistration();

    return () => {
      cancelled = true;
    };
  }, [user?.uid, eventId]);

  async function handleRegister() {
    if (!user) return;

    setRegistering(true);
    try {
      const token = await user.getIdToken();
      const userName =
        profile ?
          `${profile.firstName} ${profile.lastName}`.trim()
        : authUser?.displayName?.trim();

      const response = await fetch("/api/events/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ eventId, userName }),
      });

      const data = (await response.json()) as {
        success?: boolean;
        message?: string;
        error?: string;
        alreadyRegistered?: boolean;
      };

      if (!response.ok) {
        toast.error(data.error ?? "Unable to register. Please try again.");
        return;
      }

      setRegistered(true);
      toast.success(
        data.message ??
          `You're registered for ${eventTitle}. Check your email for details.`
      );
    } catch {
      toast.error("Unable to register. Please try again.");
    } finally {
      setRegistering(false);
    }
  }

  if (loading || checkingRegistration) {
    return (
      <Button variant="outline" size="sm" className="rounded-full" disabled>
        <Loader2 className="mr-2 size-4 animate-spin" />
        Loading...
      </Button>
    );
  }

  if (!authUser) {
    return (
      <Button asChild variant="default" size="sm" className="rounded-full">
        <Link href={`/signin?callbackUrl=/events/${eventId}`}>
          <Ticket className="mr-2 size-4" />
          Sign in to Register
        </Link>
      </Button>
    );
  }

  if (registered) {
    return (
      <Button
        variant="outline"
        size="sm"
        className="rounded-full border-emerald-500/30 text-emerald-600 dark:text-emerald-400"
        disabled
      >
        <CheckCircle2 className="mr-2 size-4" />
        Registered
      </Button>
    );
  }

  return (
    <Button
      type="button"
      variant="default"
      size="sm"
      className="rounded-full"
      disabled={registering}
      onClick={handleRegister}
    >
      {registering ?
        <>
          <Loader2 className="mr-2 size-4 animate-spin" />
          Registering...
        </>
      : <>
          <Ticket className="mr-2 size-4" />
          Register for Event
        </>
      }
    </Button>
  );
}

