"use client";



import { useEffect, useState } from "react";

import { useQueryClient } from "@tanstack/react-query";

import { Loader2, Plus } from "lucide-react";

import { useRouter } from "next/navigation";

import { toast } from "sonner";



import { OnboardingWizardShell } from "@/components/onboarding/onboarding-wizard-shell";

import { WorkspaceTypeSelector } from "@/components/onboarding/workspace-type-selector";

import { Button } from "@/components/ui/button";

import { Input } from "@/components/ui/input";

import { Label } from "@/components/ui/label";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import { useFirebaseAuth } from "@/context/firebase-auth-context";

import { setAuthSession } from "@/lib/auth/set-auth-session";

import { useOrganization } from "@/context/organization-context";

import { buildCreateWorkspaceAuthHref, WAITING_APPROVAL_PATH } from "@/lib/auth/auth-flow";

import { useWorkspaceAccess } from "@/hooks/use-workspace-access";

import { firebaseAuth } from "@/lib/firebase-auth-service";
import { buildPostOnboardingProfilePatch, isWorkspaceProfileComplete } from "@/lib/auth/wait-for-user-profile";

import { COUNTRIES } from "@/lib/countries";

import { MAX_IMAGE_SIZE_LABEL, validateImageFile } from "@/lib/upload-limits";

import type { WorkspaceType } from "@/types/organization";

import { cn } from "@/lib/utils";



export function ChurchOnboardingForm() {

  const router = useRouter();

  const queryClient = useQueryClient();

  const { authUser, refreshProfile, profileReady } = useFirebaseAuth();

  const {

    churches,

    loading: orgLoading,

    refetch,

    membership,

  } = useOrganization();

  const { isMembershipPending } = useWorkspaceAccess();



  const [step, setStep] = useState(1);

  const [workspaceType, setWorkspaceType] =

    useState<WorkspaceType>("independent_church");



  const [name, setName] = useState("");

  const [city, setCity] = useState("");

  const [country, setCountry] = useState("India");

  const [phone, setPhone] = useState("");

  const [email, setEmail] = useState("");

  const [website, setWebsite] = useState("");

  const [logoFile, setLogoFile] = useState<File | undefined>();

  const [logoPreview, setLogoPreview] = useState("");

  const [loading, setLoading] = useState(false);



  useEffect(() => {
    if (!profileReady) return;

    if (!authUser) {
      router.replace(buildCreateWorkspaceAuthHref("/signin"));
      return;
    }

    if (isMembershipPending) {
      router.replace(WAITING_APPROVAL_PATH);
    }
  }, [authUser, profileReady, isMembershipPending, router]);



  function handleLogoPick(file: File | undefined) {

    if (!file) return;

    const error = validateImageFile(file);

    if (error) {

      toast.error(error);

      return;

    }

    const reader = new FileReader();

    reader.onloadend = () => {

      setLogoFile(file);

      setLogoPreview(reader.result as string);

    };

    reader.readAsDataURL(file);

  }



  async function handleSubmit(event: React.FormEvent) {

    event.preventDefault();



    if (!name.trim()) {

      toast.error(

        workspaceType === "independent_church" ?

          "Church name is required"

        : "Organization name is required"

      );

      return;

    }



    if (!city.trim()) {

      toast.error("City is required");

      return;

    }

    if (!country.trim()) {

      toast.error("Country is required");

      return;

    }



    const user = firebaseAuth.currentUser;

    if (!user) {

      toast.error("Please sign in to continue");

      return;

    }



    setLoading(true);

    try {

      const token = await user.getIdToken();

      let logoUrl: string | undefined;
      if (logoFile) {
        const formData = new FormData();
        formData.append("file", logoFile);
        const { uploadOnboardingLogoLocal } = await import("@/lib/local-upload");
        try {
          logoUrl = await uploadOnboardingLogoLocal(
            user.uid,
            formData,
            undefined,
            token
          );
        } catch {
          toast.message("Logo upload failed. Continuing with the default logo.");
        }
      }

      const requestBody = {
        name: name.trim(),
        ...(logoUrl ? { logoUrl } : {}),
        phone: phone.trim() || undefined,
        email: email.trim() || undefined,
        website: website.trim() || undefined,
        city: city.trim(),
        state: "N/A",
        country: country.trim(),
        workspaceType,
      };

      const response = await fetch("/api/onboarding/church", {

        method: "POST",

        headers: {

          Authorization: `Bearer ${token}`,

          "Content-Type": "application/json",

        },

        body: JSON.stringify(requestBody),

      });



      if (!response.ok) {

        const body = (await response.json().catch(() => ({}))) as {

          error?: string;

        };

        throw new Error(body.error ?? "Failed to create workspace");

      }



      const result = (await response.json()) as {

        organizationId?: string;

        churchId?: string;

        branchId?: string;

        joinSlug?: string;

      };

      if (!result.organizationId?.trim()) {
        throw new Error("Workspace creation did not return an organization id.");
      }

      const profilePatch = buildPostOnboardingProfilePatch({
        organizationId: result.organizationId,
        churchId: result.churchId,
        activeBranchId: result.branchId,
      });

      if (logoFile && result.churchId && !logoUrl) {

        const formData = new FormData();

        formData.append("file", logoFile);

        const { uploadSongFileLocal } = await import("@/lib/local-upload");

        try {

          await uploadSongFileLocal(

            result.churchId,

            "cover",

            formData,

            undefined,

            token,

            { kind: "church-logo" }

          );

        } catch {

          toast.message("Workspace created. You can upload a logo from church settings.");

        }

      }



      const resolvedProfile = await refreshProfile(profilePatch);

      if (!resolvedProfile || !isWorkspaceProfileComplete(resolvedProfile)) {
        throw new Error("Failed to create workspace.");
      }

      await refetch();

      let activeMembership = membership;

      if (resolvedProfile) {
        const orgResponse = await fetch("/api/organization", {
          headers: { Authorization: `Bearer ${token}` },
        });

        if (orgResponse.ok) {
          const orgData = (await orgResponse.json()) as {
            membership?: typeof membership;
            churches?: unknown[];
          };

          activeMembership = orgData.membership ?? activeMembership;
        }

        setAuthSession(true, {
          role: resolvedProfile.role,
          profile: resolvedProfile,
          membership: activeMembership,
          churchesCount:
            workspaceType === "multi_church_org" ? 0 : churches.length + 1,
          workspaceType,
        });
      }

      await queryClient.refetchQueries({ queryKey: ["membership-routing"] });
      await queryClient.refetchQueries({ queryKey: ["organization"] });

      router.replace("/dashboard");
      router.refresh();

    } catch (error) {

      toast.error(

        error instanceof Error ? error.message : "Failed to complete onboarding"

      );

    } finally {

      setLoading(false);

    }

  }



  if (step === 1) {

    return (

      <OnboardingWizardShell

        title="Create Your Workspace"

        description="Choose how your ministry will be organized on FaithConnectHub."

      >

        <WorkspaceTypeSelector

          value={workspaceType}

          onChange={setWorkspaceType}

        />



        <div className="mt-8 flex justify-center">

          <Button

            type="button"

            className="h-11 min-w-[200px] rounded-lg px-8 text-[15px] font-medium"

            onClick={() => setStep(2)}

          >

            Continue

          </Button>

        </div>

      </OnboardingWizardShell>

    );

  }



  const isIndependent = workspaceType === "independent_church";



  return (

    <OnboardingWizardShell

      variant="form"

      title="Create Your Workspace"

      description={

        isIndependent ?

          "Tell us about your church. We will set up your workspace and join link."

        : "Tell us about your organization. You can add churches after setup."

      }

    >

      <form onSubmit={handleSubmit} className="space-y-5">

        <div className="flex flex-col items-center gap-2">
          <input
            id="logo-upload"
            type="file"
            accept="image/*"
            className="sr-only"
            disabled={loading}
            onChange={(e) => handleLogoPick(e.target.files?.[0])}
          />
          <label
            htmlFor="logo-upload"
            className={cn(
              "relative flex size-24 cursor-pointer items-center justify-center overflow-hidden rounded-full border border-border bg-accent transition-colors",
              loading
                ? "cursor-not-allowed opacity-60"
                : "hover:border-primary/40 hover:bg-accent"
            )}
          >
            {logoPreview ?
              <img
                src={logoPreview}
                alt=""
                className="size-full object-cover"
              />
            : <Plus className="size-7 text-muted-foreground" />}
          </label>
          <p className="text-xs text-muted-foreground">
            PNG or JPG, max {MAX_IMAGE_SIZE_LABEL}
          </p>
        </div>

        <div className="space-y-2">

          <Label htmlFor="workspace-name">

            {isIndependent ? "Church Name" : "Organization Name"}{" "}

            <span className="text-destructive">*</span>

          </Label>

          <Input

            id="workspace-name"

            value={name}

            onChange={(e) => setName(e.target.value)}

            placeholder={

              isIndependent ? "Grace Gospel Chapel" : "Grace Ministries Network"

            }

            required

            disabled={loading}

          />

        </div>



        <div className="grid gap-4 sm:grid-cols-2">
          <div className="space-y-2">
            <Label htmlFor="city">
              City <span className="text-destructive">*</span>
            </Label>
            <Input
              id="city"
              value={city}
              onChange={(e) => setCity(e.target.value)}
              placeholder="Enter your city"
              required
              disabled={loading}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="country">
              Country <span className="text-destructive">*</span>
            </Label>
            <Select value={country} onValueChange={setCountry} disabled={loading}>
              <SelectTrigger id="country">
                <SelectValue placeholder="Select country" />
              </SelectTrigger>
              <SelectContent>
                {COUNTRIES.map((countryOption) => (
                  <SelectItem key={countryOption} value={countryOption}>
                    {countryOption}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>



        <div className="grid gap-4 sm:grid-cols-2">

          <div className="space-y-2">

            <Label htmlFor="phone">Phone (optional)</Label>

            <Input

              id="phone"

              type="tel"

              value={phone}

              onChange={(e) => setPhone(e.target.value)}

              placeholder="+1 (555) 123-4567"

              disabled={loading}

            />

          </div>



          <div className="space-y-2">

            <Label htmlFor="email">Email (optional)</Label>

            <Input

              id="email"

              type="email"

              value={email}

              onChange={(e) => setEmail(e.target.value)}

              placeholder="hello@yourchurch.org"

              disabled={loading}

            />

          </div>

        </div>



        <div className="space-y-2">

          <Label htmlFor="website">Website (optional)</Label>

          <Input

            id="website"

            type="url"

            value={website}

            onChange={(e) => setWebsite(e.target.value)}

            placeholder="https://yourchurch.org"

            disabled={loading}

          />

        </div>



        <div className="flex flex-col-reverse gap-3 pt-2 sm:flex-row sm:justify-between">

          <Button

            type="button"

            variant="outline"

            className="h-11 rounded-lg sm:min-w-[120px]"

            disabled={loading}

            onClick={() => setStep(1)}

          >

            Back

          </Button>

          <Button

            type="submit"

            className="h-11 min-w-[200px] rounded-lg text-[15px] font-medium"

            disabled={loading}

          >

            {loading ?

              <>

                <Loader2 className="mr-2 size-4 animate-spin" />

                Creating workspace…

              </>

            : "Create workspace"}

          </Button>

        </div>

      </form>

    </OnboardingWizardShell>

  );

}

"use client";

import { useCallback, useEffect, useState } from "react";
import { Loader2, Mail, Link2, Copy } from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useFirebaseAuth } from "@/context/firebase-auth-context";
import { useOrganization } from "@/context/organization-context";
import { useAdminChurchId } from "@/hooks/use-admin-church-id";
import { firebaseAuth } from "@/lib/firebase-auth-service";
import type { FirebaseInvitation } from "@/types/invitation";
import type { MembershipRole } from "@/types/membership";

const INVITE_ROLES: { value: MembershipRole; label: string }[] = [
  { value: "org_admin", label: "Organization Admin" },
  { value: "church_admin", label: "Church Admin" },
  { value: "branch_admin", label: "Church Admin" },
  { value: "leader", label: "Leader" },
  { value: "editor", label: "Editor" },
  { value: "member", label: "Member" },
  { value: "volunteer", label: "Volunteer" },
];

export function OrganizationInvitationsPanel() {
  const { organization, churches, branchesByChurch } = useOrganization();
  const churchId = useAdminChurchId();
  const church = churches.find((c) => c.id === churchId) ?? churches[0];
  const branches = church ? (branchesByChurch[church.id] ?? []) : [];
  const defaultBranch = branches.find((b) => b.isDefault) ?? branches[0];

  const [email, setEmail] = useState("");
  const [role, setRole] = useState<MembershipRole>("member");
  const [branchId, setBranchId] = useState(defaultBranch?.id ?? "");
  const [loading, setLoading] = useState(false);
  const [invitations, setInvitations] = useState<FirebaseInvitation[]>([]);
  const [listLoading, setListLoading] = useState(true);

  const loadInvitations = useCallback(async () => {
    if (!organization) return;
    const user = firebaseAuth.currentUser;
    if (!user) return;

    setListLoading(true);
    try {
      const token = await user.getIdToken();
      const res = await fetch(
        `/api/invitations?organizationId=${encodeURIComponent(organization.id)}`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      if (res.ok) {
        const data = (await res.json()) as { invitations: FirebaseInvitation[] };
        setInvitations(data.invitations);
      }
    } finally {
      setListLoading(false);
    }
  }, [organization]);

  useEffect(() => {
    void loadInvitations();
  }, [loadInvitations]);

  useEffect(() => {
    if (defaultBranch && !branchId) setBranchId(defaultBranch.id);
  }, [defaultBranch, branchId]);

  async function createInvite(method: "email" | "link") {
    if (!organization || !church || !branchId) {
      toast.error("Select a church first");
      return;
    }

    const user = firebaseAuth.currentUser;
    if (!user) return;

    if (method === "email" && !email.trim()) {
      toast.error("Email is required");
      return;
    }

    setLoading(true);
    try {
      const token = await user.getIdToken();
      const res = await fetch("/api/invitations", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          organizationId: organization.id,
          churchId: church.id,
          branchId,
          role,
          email: method === "email" ? email.trim() : undefined,
          deliveryMethod: method,
        }),
      });

      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        throw new Error(body.error ?? "Failed to create invitation");
      }

      const data = (await res.json()) as {
        inviteLink?: string;
        emailSent?: boolean;
        message?: string;
      };

      if (method === "link" && data.inviteLink) {
        await navigator.clipboard.writeText(data.inviteLink);
        toast.success("Invitation link copied");
      } else if (method === "email" && data.emailSent === false && data.inviteLink) {
        toast.warning(data.message ?? "Invitation created but email failed to send.", {
          description: data.inviteLink,
          duration: 12000,
        });
        setEmail("");
      } else if (method === "email") {
        toast.success("Invitation sent");
        setEmail("");
      }
      await loadInvitations();
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : "Failed to create invitation"
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-6">
      <Tabs defaultValue="email">
        <TabsList>
          <TabsTrigger value="email">
            <Mail className="mr-2 size-4" />
            Email
          </TabsTrigger>
          <TabsTrigger value="link">
            <Link2 className="mr-2 size-4" />
            Link
          </TabsTrigger>
        </TabsList>

        <TabsContent value="email" className="mt-4 space-y-4 max-w-lg">
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label>Church</Label>
              <Select value={branchId} onValueChange={setBranchId}>
                <SelectTrigger>
                  <SelectValue placeholder="Select church" />
                </SelectTrigger>
                <SelectContent>
                  {branches.map((b) => (
                    <SelectItem key={b.id} value={b.id}>
                      {b.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Role</Label>
              <Select
                value={role}
                onValueChange={(v) => setRole(v as MembershipRole)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {INVITE_ROLES.map((r) => (
                    <SelectItem key={r.value} value={r.value}>
                      {r.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="space-y-2">
            <Label>Email</Label>
            <Input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="member@church.org"
            />
          </div>
          <Button disabled={loading} onClick={() => void createInvite("email")}>
            {loading ?
              <Loader2 className="mr-2 size-4 animate-spin" />
            : null}
            Send invitation
          </Button>
        </TabsContent>

        <TabsContent value="link" className="mt-4 space-y-4 max-w-lg">
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label>Church</Label>
              <Select value={branchId} onValueChange={setBranchId}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {branches.map((b) => (
                    <SelectItem key={b.id} value={b.id}>
                      {b.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Role</Label>
              <Select
                value={role}
                onValueChange={(v) => setRole(v as MembershipRole)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {INVITE_ROLES.map((r) => (
                    <SelectItem key={r.value} value={r.value}>
                      {r.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <Button
            variant="secondary"
            disabled={loading}
            onClick={() => void createInvite("link")}
          >
            <Copy className="mr-2 size-4" />
            Generate link
          </Button>
        </TabsContent>
      </Tabs>

      <div>
        <h3 className="mb-3 text-sm font-medium">Pending invitations</h3>
        {listLoading ?
          <Loader2 className="size-6 animate-spin text-muted-foreground" />
        : invitations.length === 0 ?
          <p className="text-sm text-muted-foreground">No invitations yet.</p>
        : <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Email</TableHead>
                <TableHead>Role</TableHead>
                <TableHead>Status</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {invitations.map((inv) => (
                <TableRow key={inv.id}>
                  <TableCell>{inv.email ?? "Link invitation"}</TableCell>
                  <TableCell>{inv.role}</TableCell>
                  <TableCell>{inv.status}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        }
      </div>
    </div>
  );
}

"use client";

import { List, ListX } from "lucide-react";

import type { AuthUser } from "@/context/firebase-auth-context";
import type { MyPlaylist } from "@/types/user-library";

import { Button } from "../ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../ui/dialog";
import { Separator } from "../ui/separator";
import { NewPlaylistForm } from "./new-playlist-form";

type AddToPlaylistDialogProps = {
  user?: AuthUser;
  isDialogOpen: boolean;
  setDialogOpen: (open: boolean) => void;
  playlists?: MyPlaylist[];
  addToPlaylist: (id: string, name: string) => void;
